function setRagProgress(percent,title,stage,summary,detail,model=''){const box=$('ragProgress');if(!box)return;const value=Math.max(0,Math.min(100,Math.round(percent)));box.hidden=false;$('ragProgressTitle').textContent=title;$('ragProgressPercent').textContent=`${value}%`;$('ragProgressStage').textContent=stage;$('ragProgressModel').textContent=model?`임베딩 모델 · ${model}`:'임베딩 모델 확인 중';$('ragProgressSummary').textContent=summary;$('ragProgressDetail').textContent=detail;$('ragProgressBar').style.width=`${value}%`;box.querySelector('[role="progressbar"]')?.setAttribute('aria-valuenow',String(value))}
function startRagProgress(model){const started=Date.now(),stages=[{at:0,title:'RAG 인덱스를 준비하고 있습니다',stage:'1 · 자료 확인',summary:'등록된 성경과 교리 자료를 확인합니다.',detail:'인덱싱 요청을 준비하는 중입니다.'},{at:18,title:'임베딩 모델에 연결하고 있습니다',stage:'2 · LM Studio 임베딩',summary:'선택한 임베딩 모델에 검색용 벡터 변환을 요청합니다.',detail:`모델: ${model||'선택 모델'}`},{at:42,title:'성경 본문을 벡터화하고 있습니다',stage:'3 · 성경 임베딩',summary:'성경 구절을 의미검색용 벡터로 변환해 SQLite에 저장합니다.',detail:'성경 자료를 배치 단위로 처리하는 중입니다.'},{at:72,title:'교리 자료를 벡터화하고 있습니다',stage:'4 · 교리 임베딩',summary:'등록된 교리 문서를 같은 임베딩 기준으로 연결합니다.',detail:'교리 근거가 있으면 함께 인덱싱합니다.'},{at:92,title:'인덱스 무결성을 확인하고 있습니다',stage:'5 · 인덱스 검증',summary:'저장된 벡터 수와 선택 모델 연결 상태를 확인합니다.',detail:'완료 응답을 기다리는 중입니다.'}];const times=[0,3500,9000,16000,26000];let index=0,timer=null;const tick=()=>{const elapsed=Date.now()-started;$('ragProgressElapsed').textContent=`${Math.floor(elapsed/1000)}초`;const next=Math.min(stages.length-1,index+1);if(index<stages.length-1&&elapsed>=times[next])index=next;const current=stages[index],nextStage=stages[index+1],ratio=nextStage?Math.min(.85,(elapsed-times[index])/Math.max(1,times[index+1]-times[index])):0;setRagProgress(current.at+(nextStage?.at-current.at||0)*ratio,current.title,current.stage,current.summary,current.detail,model);timer=requestAnimationFrame(tick)};setRagProgress(3,stages[0].title,stages[0].stage,stages[0].summary,stages[0].detail,model);timer=requestAnimationFrame(tick);return{finish(d){if(timer)cancelAnimationFrame(timer);setRagProgress(100,'RAG 인덱스 생성이 완료되었습니다','완료 · 의미검색 사용 가능',`성경 ${Number(d.indexed||0).toLocaleString()}건 · 교리 ${Number(d.doctrine_indexed||0).toLocaleString()}건을 인덱싱했습니다.`,'선택한 임베딩 모델과 인덱스 연결을 확인했습니다.',model)},fail(message){if(timer)cancelAnimationFrame(timer);setRagProgress(0,'RAG 인덱스 생성이 중단되었습니다','중단 · 확인 필요','벡터 인덱스가 완성되지 않았습니다.',message,model)}}}
$('buildRag').onclick=async()=>{const model=$('embeddingModel').value;if(!model){alert('LM Studio에서 임베딩 모델을 로드하고 선택하세요.');return}if(Number(lastHealth?.database?.passages||0)<1){$('ragStatus').textContent='인덱싱 불가 · 성경 자료가 0건입니다. 먼저 성경 자료를 등록하세요.';renderRagSetup();return}const btn=$('buildRag');btn.disabled=true;const progress=startRagProgress(model);$('ragStatus').textContent='성경과 교리 자료를 벡터로 변환하고 있습니다…';try{const r=await fetch('/api/rag/reindex',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'인덱싱 실패');$('ragStatus').textContent=`완료 · 성경 ${d.indexed}건 · 교리 ${d.doctrine_indexed}건 · ${d.model}`;progress.finish(d);await checkHealth()}catch(e){$('ragStatus').textContent='인덱싱 실패 · '+e.message;progress.fail(e.message)}finally{btn.disabled=false;renderRagSetup()}};
function selectedImportPreset(){return importPresets.find(x=>x.id===$('importPreset').value)||null}
function resetBibleImport(message='자료와 원본 형식을 선택한 뒤 변환 · 미리보기를 실행하세요.'){pendingBibleImport=[];$('bibleImportPreview').textContent='아직 변환한 원본 파일이 없습니다.';$('bibleImportStatus').className='import-status';$('bibleImportStatus').textContent=message;$('runBibleImport').disabled=true;$('importToRag').disabled=true}
function applyImportPreset(){const p=selectedImportPreset(),custom=p?.kind==='licensed_custom';['importTranslation','importLanguage','importLicense','importSource'].forEach(id=>$(id).readOnly=!custom);$('importTranslation').value=p?.translation||'';$('importLanguage').value=p?.language||'';$('importLicense').value=p?.license_note||'';$('importSource').value=p?.source_url||'';const format=$('bibleSourceFormat');format.value='auto';format.disabled=!custom;$('bibleFormatHelp').textContent=custom?'허가받은 사용자 자료만 필요할 때 형식을 직접 지정할 수 있습니다.':'공개자료는 프로그램이 자동 판별하므로 바꿀 필요가 없습니다.';if(!p){$('importPresetInfo').textContent='공개 자료 프리셋 또는 정식 허가자료를 선택하세요.'}else if(custom){$('importPresetInfo').innerHTML='정식 허가자료는 아래 <b>번역본 사용권 등록부</b>에 같은 번역명을 먼저 등록하고 <b>전문 DB 저장 허용</b>을 켜야 합니다.'}else{$('importPresetInfo').innerHTML=`${esc(p.license_note)} · <a href="${esc(p.source_url)}" target="_blank" rel="noopener noreferrer">공식 출처 확인</a>`}let guide='자료를 선택한 뒤 성경 원본 파일을 고르세요.';if(p?.id==='web')guide='<b>WEB:</b> 내려받은 <code>engwebp_usfm.zip</code>을 압축 풀지 말고 그대로 선택하세요.';else if(p?.id==='sblgnt')guide='<b>SBLGNT:</b> 마태복음은 <code>Matt.xml</code>, 신약 전체는 <code>sblgnt.xml</code>을 선택하세요. <code>LexicalIndex.xml</code>은 성경 본문이 아니므로 프로그램이 차단합니다.';else if(p?.id==='wlc')guide='<b>WLC:</b> 성경 구절 본문이 들어 있는 공식 WLC 파일을 선택하세요. 형태론·lemma용 OSHB 파일은 원어 근거 가져오기에서 사용합니다.';$('bibleSimpleGuide').innerHTML=guide;resetBibleImport(p?.id==='sblgnt'?'SBLGNT를 선택했습니다. 이제 Matt.xml 또는 sblgnt.xml 파일만 고른 뒤 미리보기를 누르세요.':p?.id==='web'?'WEB를 선택했습니다. 이제 engwebp_usfm.zip 파일만 고른 뒤 미리보기를 누르세요.':'자료를 선택했습니다. 파일을 고른 뒤 미리보기를 누르세요.')}
async function loadImportPresets(){try{const r=await fetch('/api/import/presets',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error('프리셋 조회 실패');importPresets=d.items||[];$('importPreset').innerHTML='<option value="">자료 프리셋 선택</option>'+importPresets.map(x=>`<option value="${esc(x.id)}">${esc(x.label)}</option>`).join('');$('bibleImportStatus').textContent=d.notice||'자료 프리셋을 선택하세요.'}catch(e){$('importPreset').innerHTML='<option value="">프리셋 조회 실패</option>';$('bibleImportStatus').className='import-status bad';$('bibleImportStatus').textContent='가져오기 설정을 불러오지 못했습니다: '+e.message}}
function importReference(item){const direct=String(item?.reference||'').trim();if(direct)return direct;const book=String(item?.book||'').trim(),chapter=String(item?.chapter||'').trim(),verse=String(item?.verse||'').trim();return book&&chapter&&verse?`${book} ${chapter}:${verse}`:''}
async function previewBibleImport(){const p=selectedImportPreset(),file=$('bibleImportFile').files?.[0];if(!p){$('bibleImportStatus').className='import-status warn';$('bibleImportStatus').textContent='먼저 자료 프리셋을 선택하세요.';return}if(!file){$('bibleImportStatus').className='import-status warn';$('bibleImportStatus').textContent='성경 원본 파일을 선택하세요.';return}if(/^lexicalindex\.xml$/i.test(file.name)){$('bibleImportPreview').textContent='선택한 LexicalIndex.xml은 SBLGNT 성경 구절 본문이 아니라 어휘 색인 파일입니다.\n\n마태복음은 공식 data/sblgnt/xml/Matt.xml을 선택하세요. 신약 전체는 같은 폴더의 sblgnt.xml을 사용할 수 있습니다.';$('bibleImportStatus').className='import-status warn';$('bibleImportStatus').textContent='SBLGNT 본문 파일(Matt.xml 또는 sblgnt.xml)을 선택하세요.';pendingBibleImport=[];updateBibleImportButton();return}if(file.size>50*1024*1024){$('bibleImportStatus').className='import-status bad';$('bibleImportStatus').textContent='파일이 50MB를 넘습니다. 더 작은 원본 파일로 나누세요.';return}const button=$('previewBibleImport'),selectedFormat=$('bibleSourceFormat').value,isZip=selectedFormat==='usfm_zip'||file.name.toLowerCase().endsWith('.zip');button.disabled=true;$('bibleImportStatus').className='import-status';$('bibleImportStatus').textContent=isZip?'ZIP 내부 파일과 USFM 구조를 안전하게 검사하고 전체 구절을 모으고 있습니다…':'원본 형식을 분석하고 프로그램용 구절 목록으로 변환하고 있습니다…';try{let r;if(isZip){r=await fetch('/api/import/convert-usfm-zip',{method:'POST',headers:{'Content-Type':'application/zip'},body:file})}else{const content=await file.text();r=await fetch('/api/import/convert',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_format:selectedFormat,content})})}const d=await r.json();if(!r.ok)throw new Error(d.detail||'원본 변환 실패');pendingBibleImport=d.items||[];const sample=pendingBibleImport.slice(0,5).map((x,i)=>`${i+1}. ${x.reference} · ${x.text.slice(0,100)}${x.text.length>100?'…':''}`).join('\n'),fileInfo=d.file_count?` · USFM ${Number(d.file_count).toLocaleString()}파일`:'';$('bibleImportPreview').textContent=`변환 통과 · ${String(d.source_format).toUpperCase()}${fileInfo} · 총 ${Number(d.count||0).toLocaleString()}구절\n\n${sample}${pendingBibleImport.length>5?'\n\n… 전체 구절의 중복·필수값 검사를 통과했습니다.':''}`;$('bibleImportStatus').className='import-status ok';$('bibleImportStatus').textContent=`원본 변환·검사 통과 · ${pendingBibleImport.length.toLocaleString()}구절${fileInfo} · 사용조건 확인 후 DB에 가져오세요.`;updateBibleImportButton()}catch(e){pendingBibleImport=[];$('bibleImportPreview').textContent='변환 실패 · '+e.message;$('bibleImportStatus').className='import-status bad';$('bibleImportStatus').textContent=e.message.includes('_read.txt')?'read-aloud 파일이 아니라 eBible의 engwebp_usfm.zip을 선택하세요.':e.message;updateBibleImportButton()}finally{button.disabled=false}}
function updateBibleImportButton(){$('runBibleImport').disabled=!(pendingBibleImport.length&&$('confirmBibleLicense').checked&&selectedImportPreset())}
async function importBibleBatchWithRetry(body,maxAttempts=4){let lastError;for(let attempt=1;attempt<=maxAttempts;attempt++){try{const r=await fetch('/api/import/bible',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json().catch(()=>({}));if(r.ok)return d;const error=new Error(d.detail||`DB 등록 실패 (HTTP ${r.status})`);if(r.status<500)throw Object.assign(error,{permanent:true});throw error}catch(e){lastError=e;if(e.permanent||attempt===maxAttempts)throw e;$('bibleImportStatus').className='import-status warn';$('bibleImportStatus').textContent=`로컬 서버 응답이 끊겼습니다. 같은 배치를 자동 재시도합니다 (${attempt}/${maxAttempts-1})…`;await new Promise(resolve=>setTimeout(resolve,500*attempt))}}throw lastError}
async function runBibleImport(){const p=selectedImportPreset();if(!p||!pendingBibleImport.length||!$('confirmBibleLicense').checked)return;const translation=$('importTranslation').value.trim(),language=$('importLanguage').value.trim(),license_note=$('importLicense').value.trim(),source_url=$('importSource').value.trim();if(p.kind==='licensed_custom'&&(!translation||!language||!license_note||!source_url)){$('bibleImportStatus').className='import-status warn';$('bibleImportStatus').textContent='사용자 허가자료는 번역명·언어·사용조건·공식 출처 URL을 모두 입력하세요.';return}const btn=$('runBibleImport');btn.disabled=true;let processed=0;try{for(let start=0;start<pendingBibleImport.length;start+=1000){const chunk=pendingBibleImport.slice(start,start+1000);$('bibleImportStatus').className='import-status';$('bibleImportStatus').textContent=`DB 등록 중… ${processed.toLocaleString()} / ${pendingBibleImport.length.toLocaleString()}건`;const body={preset_id:p.id,translation,language,license_note,source_url,confirmed:true,items:chunk};await importBibleBatchWithRetry(body);processed=start+chunk.length}$('bibleImportStatus').className='import-status ok';$('bibleImportStatus').textContent=`DB 등록 완료 · ${processed.toLocaleString()}건 처리 · 기존 저장 구절은 안전하게 갱신됨 · RAG 인덱스를 새로 만드세요.`;$('importToRag').disabled=false;await checkHealth();await loadDatabaseDashboard()}catch(e){$('bibleImportStatus').className='import-status bad';$('bibleImportStatus').textContent=`등록 중단 · ${processed.toLocaleString()}건 응답 확인 · ${e.message} · 원본을 다시 검사한 뒤 재실행해도 중복되지 않습니다.`}finally{updateBibleImportButton()}}
function renderDatabaseDashboard(d){const db=d.database||{},rag=d.rag||{},rows=d.translations||[];$('databaseSummary').innerHTML=[['성경 본문',Number(db.passages||0).toLocaleString()+'건'],['번역/자료',Number(db.translations||0)+'종'],['언어',Number(db.languages||0)+'종'],['RAG 벡터',Number(rag.indexed||0).toLocaleString()+'건']].map(x=>`<div class="db-stat"><small>${esc(x[0])}</small><b>${esc(x[1])}</b></div>`).join('');$('databaseTranslations').innerHTML=rows.length?rows.map(row=>{const permission=Number(row.allow_fulltext)===-1?'등록 없음':Number(row.allow_fulltext)===1?`${esc(row.license_status)} · 저장 허용`:`${esc(row.license_status)} · 저장 OFF`;return `<tr><td><b>${esc(row.translation)}</b></td><td>${esc(row.language)}</td><td>${Number(row.passages).toLocaleString()}</td><td>${Number(row.references_count).toLocaleString()}</td><td>${Number(row.rag_vectors).toLocaleString()}</td><td>${permission}</td><td><button type="button" class="db-delete" data-translation="${esc(row.translation)}">이 번역 삭제</button></td></tr>`}).join(''):'<tr><td colspan="7">등록된 성경 자료가 없습니다.</td></tr>';document.querySelectorAll('.db-delete').forEach(button=>button.onclick=()=>deleteDatabaseTranslation(button.dataset.translation))}
async function loadDatabaseDashboard(){loadOriginalLanguageDashboard();try{const r=await fetch('/api/database/dashboard',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.detail||'DB 조회 실패');renderDatabaseDashboard(d)}catch(e){$('databaseSummary').innerHTML='DB 대시보드 오류: '+esc(e.message);$('databaseTranslations').innerHTML='<tr><td colspan="7">DB 상태를 불러오지 못했습니다.</td></tr>'}}
async function loadOriginalLanguageDashboard(){const box=$('originalGuideSummary');if(!box)return;try{const r=await fetch('/api/original-language/dashboard',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.detail||'원어 자료 상태 조회 실패');const s=d.sources||{},db=d.database||{};const card=(value,label,detail)=>`<div><b>${esc(value)}</b><small>${esc(label)} · ${esc(detail)}</small></div>`;box.innerHTML=[card(`${Number(s.sblgnt?.files||0)}/${Number(s.sblgnt?.expected||0)}개`,'SBLGNT 본문',`${Number(db.sblgnt_verses||0).toLocaleString()}절 DB`),card(`${Number(s.morphgnt?.files||0)}/${Number(s.morphgnt?.expected||0)}개`,'MorphGNT 형태론',`${Number(db.morphgnt_tokens||0).toLocaleString()} token`),card(`${Number(s.apparatus?.files||0)}/${Number(s.apparatus?.expected||0)}개`,'Apparatus 본문비평',`${Number(db.apparatus_notes||0).toLocaleString()} note`),card(`${Number(db.original_notes||0).toLocaleString()}건`,'원어 근거 등록',d.metadata?.available?'출처·checksum 기록됨':'출처 기록 확인 필요')].join('')}catch(e){box.innerHTML=`<div class="guide-status-error" role="status"><b>상태 조회 실패</b><small>${esc(e.message)}</small></div>`}}
async function checkDatabaseIntegrity(){const box=$('databaseIntegrity');box.className='db-integrity';box.textContent='SQLite와 본문/RAG 연결 상태를 검사하고 있습니다…';try{const r=await fetch('/api/database/integrity',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.detail||'무결성 검사 실패');box.className='db-integrity '+(d.ok?'ok':'bad');box.textContent=d.ok?`무결성 정상 · SQLite ${d.quick_check} · 빈 본문 0 · 고아 벡터 0 · 사용권 충돌 0`:`확인 필요 · ${(d.issues||[]).join(' · ')}`}catch(e){box.className='db-integrity bad';box.textContent='무결성 검사 오류: '+e.message}}
async function deleteDatabaseTranslation(translation){if(!translation)return;if(!confirm(`"${translation}"의 모든 성경 본문과 연결된 RAG 벡터를 삭제하시겠습니까?\n사용권 등록 기록은 보존됩니다.`))return;try{const params=new URLSearchParams({translation,confirm:translation}),r=await fetch(`/api/database/translation?${params.toString()}`,{method:'DELETE'}),d=await r.json();if(!r.ok)throw new Error(d.detail||'삭제 실패');alert(`${translation} · 본문 ${Number(d.deleted_passages)}건 · RAG 벡터 ${Number(d.deleted_vectors)}건을 삭제했습니다.`);renderDatabaseDashboard(d.dashboard);await checkHealth();await checkDatabaseIntegrity()}catch(e){alert('삭제 오류: '+e.message)}}
function backupBytes(value){const n=Number(value||0);return n<1024?`${n} B`:n<1024*1024?`${(n/1024).toFixed(1)} KB`:`${(n/1024/1024).toFixed(1)} MB`}
async function loadBackups(){const box=$('backupStatus');try{const r=await fetch('/api/backups',{cache:'no-store'}),d=await apiJson(r,'백업 목록 조회 실패');if(!r.ok)throw new Error(d.detail||'백업 목록 조회 실패');const items=d.items||[];box.className='db-integrity ok';box.textContent=items.length?`로컬 통합 백업 ${items.length}개 · 최신순으로 표시합니다.`:'아직 만든 통합 백업이 없습니다.';$('backupList').innerHTML=items.length?items.map(item=>item.valid?`<div class="backup-item"><div><b>${esc(item.filename)}</b><small>${esc(item.created_at||'시간 미기록')} · V${esc(item.app_version||'?')} · ${esc(item.reason==='pre_restore'?'복원 전 자동백업':'수동백업')} · 성경 ${Number(item.passages||0).toLocaleString()}건 · 설교 ${Number(item.sermons||0).toLocaleString()}건 · ${backupBytes(item.size_bytes)}</small></div><a href="/api/backups/download/${encodeURIComponent(item.filename)}">다운로드</a></div>`:`<div class="backup-item bad"><div><b>${esc(item.filename)}</b><small>검증 실패 · ${esc(item.error||'손상된 백업')}</small></div></div>`).join(''):'<div class="backup-item"><div>백업을 만들면 이곳에 표시됩니다.</div></div>'}catch(e){box.className='db-integrity bad';box.textContent='백업 목록 오류: '+e.message;$('backupList').innerHTML=''}}
async function createLocalBackup(){const btn=$('createBackup');btn.disabled=true;$('backupStatus').className='db-integrity';$('backupStatus').textContent='SQLite 스냅샷을 만들고 해시·무결성을 검증하고 있습니다…';try{const r=await fetch('/api/backups',{method:'POST'}),d=await apiJson(r,'백업 생성 실패');if(!r.ok)throw new Error(d.detail||'백업 생성 실패');await loadBackups();window.location.href=d.url}catch(e){$('backupStatus').className='db-integrity bad';$('backupStatus').textContent='백업 생성 오류: '+e.message}finally{btn.disabled=false}}
async function restoreLocalBackup(){const file=$('restoreBackupFile').files?.[0];if(!file){alert('복원할 통합 백업 ZIP을 먼저 선택하세요.');return}if(file.size>512*1024*1024){alert('백업 파일은 최대 512MB까지 복원할 수 있습니다.');return}if(!confirm(`"${file.name}"에서 데이터베이스를 복원하시겠습니까?\n\n현재 DB는 먼저 자동 백업됩니다. 복원 파일의 설교·성경·설정 상태로 바뀝니다.`))return;const btn=$('restoreBackup');btn.disabled=true;$('backupStatus').className='db-integrity';$('backupStatus').textContent='백업 형식·해시·SQLite 무결성을 검사한 뒤 복원하고 있습니다…';try{const r=await fetch('/api/backups/restore?confirm=RESTORE',{method:'POST',headers:{'Content-Type':'application/zip'},body:file}),d=await apiJson(r,'복원 실패');if(!r.ok)throw new Error(d.detail||'복원 실패');$('backupStatus').className='db-integrity ok';$('backupStatus').textContent=`복원 완료 · 현재 상태의 자동 안전백업 ${d.pre_restore_backup?.filename||''}도 보존했습니다.`;await Promise.all([loadBackups(),loadDatabaseDashboard(),loadReadingSpeed(),checkHealth(),refreshSaved(),loadProjectDashboard()]);alert('복원이 완료되었습니다. 현재 DB는 복원 파일 기준이며, 복원 직전 상태도 자동 백업으로 보존했습니다.')}catch(e){$('backupStatus').className='db-integrity bad';$('backupStatus').textContent='복원 중단 · '+e.message}finally{btn.disabled=false}}
$('importPreset').addEventListener('change',applyImportPreset);$('bibleSourceFormat').addEventListener('change',()=>resetBibleImport('원본 형식을 바꿨습니다. 다시 변환 · 미리보기를 실행하세요.'));$('bibleImportFile').addEventListener('change',()=>{const f=$('bibleImportFile').files?.[0],name=f?.name?.toLowerCase()||'',readBad=name.endsWith('_read.txt'),lexicalBad=name==='lexicalindex.xml',bad=readBad||lexicalBad;$('previewBibleImport').disabled=bad;if(lexicalBad){$('bibleImportPreview').textContent='이 파일은 성경 구절 본문이 아니라 SBLGNT 어휘 색인입니다.\n\n마태복음: Matt.xml\n신약 전체: sblgnt.xml';resetBibleImport('LexicalIndex.xml은 사용하지 않습니다. Matt.xml 또는 sblgnt.xml을 선택하세요.');$('bibleImportPreview').textContent='선택 차단 · LexicalIndex.xml은 성경 본문 파일이 아닙니다.\n\n마태복음은 Matt.xml, 신약 전체는 sblgnt.xml을 선택하세요.';return}resetBibleImport(readBad?'선택한 *_read.txt는 read-aloud용입니다. eBible의 engwebp_usfm.zip을 선택하세요.':'파일을 선택했습니다. 이제 원본 변환 · 미리보기만 누르세요.')});$('confirmBibleLicense').addEventListener('change',updateBibleImportButton);$('previewBibleImport').onclick=previewBibleImport;$('runBibleImport').onclick=runBibleImport;$('importToRag').onclick=()=>document.querySelector('.rag-box').scrollIntoView({behavior:'smooth',block:'center'});$('refreshDatabase').onclick=loadDatabaseDashboard;$('checkDatabaseIntegrity').onclick=checkDatabaseIntegrity;$('databaseToRag').onclick=()=>document.querySelector('.rag-box').scrollIntoView({behavior:'smooth',block:'center'});$('createBackup').onclick=createLocalBackup;$('refreshBackups').onclick=loadBackups;$('restoreBackup').onclick=restoreLocalBackup;
$('recommendBtn').onclick=async()=>{const reference=$('reference').value.trim(),model=$('embeddingModel').value;if(!reference){alert('중심본문을 먼저 입력하세요.');return}if(!model){alert('임베딩 모델을 선택하세요.');return}$('recommendResults').innerHTML='<p>관련구절을 의미검색하고 있습니다…</p>';try{const r=await fetch(`/api/recommend?reference=${encodeURIComponent(reference)}&model=${encodeURIComponent(model)}`),d=await r.json();if(!r.ok)throw new Error(d.detail||'추천 실패');$('recommendResults').innerHTML=d.items.length?d.items.map(x=>`<article class="recommend-card"><b>${esc(x.reference)}</b> · ${esc(x.translation)}<br>${esc(x.text)}<br><small>유사도 ${Number(x.semantic_score||0).toFixed(3)}</small></article>`).join(''):'<p>추천할 관련구절이 없습니다. 중심본문과 RAG 인덱스를 확인하세요.</p>'}catch(e){$('recommendResults').innerHTML='<p>오류: '+esc(e.message)+'</p>'}};
function setSmartStep(step){document.querySelectorAll('.smart-step').forEach((node,index)=>node.classList.toggle('active',index<step))}
function resetSmartOriginal(message='먼저 파일을 선택하고 “파일 종류 확인하기”를 누르세요.'){smartOriginalRole=null;smartOriginalFormat='auto';smartOriginalFile=null;pendingSmartBibleImport=[];pendingOriginalImport=[];pendingOriginalZipReady=false;pendingLexiconImport=[];$('smartRoleCard').className='smart-role-card';$('smartRoleCard').textContent='파일을 선택하면 프로그램이 등록 위치를 결정합니다.';$('smartOriginalPreview').textContent='아직 검사한 파일이 없습니다.';$('smartOriginalStatus').className='import-status';$('smartOriginalStatus').textContent=message;$('smartOriginalSource').value='';$('smartOriginalLicense').value='';$('confirmSmartOriginal').checked=false;$('runSmartOriginal').disabled=true;setSmartStep(1)}
function smartSourceDefaults(role){if(role==='sblgnt_bible')return['SBL Greek New Testament (SBLGNT)','CC BY 4.0 · 출처 표시 필요'];if(role==='morphgnt_original')return['MorphGNT: SBLGNT Edition (morphgnt/sblgnt)','SBLGNT text: CC BY 4.0 · MorphGNT parsing/lemma: CC BY-SA'];if(role==='oshb_original')return['Open Scriptures Hebrew Bible (OSHB / MorphHB)','WLC text: Public Domain · OSHB lemma/morphology: CC BY 4.0'];if(role==='strongs_greek_lexicon')return["Strong's Greek Dictionary XML (morphgnt/strongs-dictionary-xml)",'CC0 · 공식 배포 조건 확인'];if(role==='hebrew_strongs_lexicon')return['Open Scriptures HebrewLexicon · HebrewStrong.xml','CC BY 4.0 · 출처 표시 필요'];return['','']}
function updateSmartOriginalButton(){const ready=smartOriginalRole==='bible_passages'?pendingSmartBibleImport.length:smartOriginalRole==='original_notes'?(pendingOriginalImport.length||pendingOriginalZipReady):smartOriginalRole==='lexicon'?pendingLexiconImport.length:false;$('runSmartOriginal').disabled=!(ready&&$('confirmSmartOriginal').checked&&$('smartOriginalSource').value.trim()&&$('smartOriginalLicense').value.trim())}
async function previewSmartOriginal(){const file=$('smartOriginalFile').files?.[0];if(!file){resetSmartOriginal('등록할 파일을 먼저 선택하세요.');return}if(file.size>50*1024*1024){resetSmartOriginal('파일은 50MB 이하여야 합니다.');$('smartOriginalStatus').className='import-status bad';return}smartOriginalFile=file;pendingSmartBibleImport=[];pendingOriginalImport=[];pendingOriginalZipReady=false;pendingLexiconImport=[];$('previewSmartOriginal').disabled=true;$('smartOriginalStatus').className='import-status';$('smartOriginalStatus').textContent=`${file.name}의 종류와 내부 구조를 검사하고 있습니다…`;try{let classified;if(/\.zip$/i.test(file.name)){classified={role:'oshb_original',target:'original_notes',format:'oshb_zip',label:'구약 OSHB 원문 근거 ZIP'}}else{const sample=await file.slice(0,131072).text(),r=await fetch('/api/import/original-language/classify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:sample,filename:file.name})}),d=await apiJson(r,'파일 종류 판별 실패');if(!r.ok)throw new Error(d.detail||'파일 종류 판별 실패');classified=d}if(!['bible_passages','original_notes','lexicon'].includes(classified.target))throw new Error('지원하는 원어 자료로 판별하지 못했습니다. 파일 이름과 형식을 확인하세요.');smartOriginalRole=classified.target;smartOriginalFormat=classified.format||'auto';const defaults=smartSourceDefaults(classified.role);$('smartOriginalSource').value=defaults[0];$('smartOriginalLicense').value=defaults[1];$('smartRoleCard').className='smart-role-card ok';$('smartRoleCard').textContent=classified.target==='bible_passages'?`자동 판별: ${classified.label} · 헬라어 성경 본문 DB에 등록합니다. lemma·형태 정보는 MorphGNT 파일로 별도 보강합니다.`:classified.target==='lexicon'?`자동 판별: ${classified.label} · 뜻/음역 사전 DB에 등록합니다.`:`자동 판별: ${classified.label} · 성경 절별 원어 근거 DB에 등록합니다.`;if(smartOriginalFormat==='oshb_zip'){const r=await fetch('/api/import/original-notes/oshb-zip/preview',{method:'POST',headers:{'Content-Type':'application/zip'},body:file}),d=await apiJson(r,'OSHB ZIP 검사 실패');if(!r.ok)throw new Error(d.detail||'OSHB ZIP 검사 실패');pendingOriginalZipReady=true;const sample=(d.sample||[]).slice(0,5).map((x,i)=>`${i+1}. ${x.reference} · ${x.language} · ${x.lemma} · ${x.morphology||'형태 미기록'}`).join('\n');$('smartOriginalPreview').textContent=`검사 통과 · ${classified.label}\n성경책 ${Number(d.book_count||0)}권 · 원어 근거 ${Number(d.count||0).toLocaleString()}건\n\n${sample}`}else{const content=await file.text(),endpoint=classified.target==='bible_passages'?'/api/import/convert':classified.target==='lexicon'?'/api/import/original-lexicon/convert':'/api/import/original-notes/convert',r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_format:smartOriginalFormat,content})}),d=await apiJson(r,'파일 변환 실패');if(!r.ok)throw new Error(d.detail||'파일 변환 실패');const items=d.items||[];if(classified.target==='bible_passages')pendingSmartBibleImport=items;else if(classified.target==='lexicon')pendingLexiconImport=items;else pendingOriginalImport=items;const sample=items.slice(0,5).map((x,i)=>classified.target==='bible_passages'?`${i+1}. ${x.reference} · ${x.text.slice(0,90)}${x.text.length>90?'…':''}`:classified.target==='lexicon'?`${i+1}. ${x.language} · ${x.lemma} · ${x.gloss} · ${x.transliteration||'음역 미기록'}`:`${i+1}. ${x.reference} · ${x.language} · ${x.lemma} · ${x.morphology||'형태 미기록'}`).join('\n');$('smartOriginalPreview').textContent=`검사 통과 · ${classified.label} · ${Number(d.count||items.length).toLocaleString()}건\n\n${sample}`}setSmartStep(2);$('smartOriginalStatus').className='import-status ok';$('smartOriginalStatus').textContent='파일 검사가 끝났습니다. 자동 입력된 출처·사용조건을 공식 배포 페이지와 대조한 뒤 확인란을 선택하세요.';updateSmartOriginalButton()}catch(e){smartOriginalRole=null;pendingSmartBibleImport=[];pendingOriginalImport=[];pendingOriginalZipReady=false;pendingLexiconImport=[];$('smartRoleCard').className='smart-role-card warn';$('smartRoleCard').textContent='자동 판별 또는 구조 검사에 실패했습니다.';$('smartOriginalPreview').textContent='검사 실패 · '+e.message;$('smartOriginalStatus').className='import-status bad';$('smartOriginalStatus').textContent=e.message;$('runSmartOriginal').disabled=true;setSmartStep(1)}finally{$('previewSmartOriginal').disabled=false}}
