function updateLexiconImportButton(){$('runLexiconImport').disabled=!(pendingLexiconImport.length&&$('confirmLexiconImport').checked&&$('lexiconImportSource').value.trim()&&$('lexiconImportLicense').value.trim())}
async function previewLexiconImport(){const file=$('lexiconImportFile').files?.[0];if(!file){$('lexiconImportStatus').className='import-status warn';$('lexiconImportStatus').textContent='원어 사전 파일을 선택하세요.';return}if(file.size>50*1024*1024){$('lexiconImportStatus').className='import-status bad';$('lexiconImportStatus').textContent='원어 사전 파일은 50MB 이하여야 합니다.';return}const btn=$('previewLexiconImport');btn.disabled=true;$('lexiconImportStatus').textContent='사전의 lemma·뜻·음역과 중복을 검사하고 있습니다…';try{const content=await file.text(),r=await fetch('/api/import/original-lexicon/convert',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source_format:$('lexiconImportFormat').value,content})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'원어 사전 변환 실패');pendingLexiconImport=d.items||[];const sample=pendingLexiconImport.slice(0,6).map((x,i)=>`${i+1}. ${x.language} · ${x.lemma} · ${x.gloss} · ${x.transliteration||'음역 미기록'}`).join('\n');$('lexiconImportPreview').textContent=`검사 통과 · ${String(d.source_format).toUpperCase()} · ${Number(d.count||0).toLocaleString()}건\n\n${sample}${pendingLexiconImport.length>6?'\n\n… 나머지 사전 항목도 같은 규칙으로 검사되었습니다.':''}`;$('lexiconImportStatus').className='import-status ok';$('lexiconImportStatus').textContent=`원어 사전 ${pendingLexiconImport.length.toLocaleString()}건 검사 통과 · 출처/사용조건 확인 후 등록하세요.`;updateLexiconImportButton()}catch(e){pendingLexiconImport=[];$('lexiconImportPreview').textContent='검사 실패 · '+e.message;$('lexiconImportStatus').className='import-status bad';$('lexiconImportStatus').textContent=e.message.includes('원어 근거')?'이 파일은 뜻 사전이 아닙니다. 위 원어 근거 가져오기에서 등록하세요.':'사전 파일 형식과 lemma·뜻 항목을 확인하세요.';updateLexiconImportButton()}finally{btn.disabled=false}}
async function runLexiconImport(){if($('runLexiconImport').disabled)return;const source=$('lexiconImportSource').value.trim(),license_note=$('lexiconImportLicense').value.trim(),btn=$('runLexiconImport');btn.disabled=true;let imported=0,updated=0,unchanged=0;try{for(let start=0;start<pendingLexiconImport.length;start+=1000){$('lexiconImportStatus').textContent=`원어 사전 DB 등록 중… ${start.toLocaleString()} / ${pendingLexiconImport.length.toLocaleString()}건`;const r=await fetch('/api/import/original-lexicon',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source,license_note,confirmed:true,items:pendingLexiconImport.slice(start,start+1000)})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'원어 사전 등록 실패');imported+=Number(d.imported||0);updated+=Number(d.updated||0);unchanged+=Number(d.unchanged||0)}$('lexiconImportStatus').className='import-status ok';$('lexiconImportStatus').textContent=`원어 사전 등록 완료 · 신규 ${imported.toLocaleString()}건 · 갱신 ${updated.toLocaleString()}건 · 동일 ${unchanged.toLocaleString()}건`;if($('oReference').value.trim())await loadOriginalNotes()}catch(e){$('lexiconImportStatus').className='import-status bad';$('lexiconImportStatus').textContent=`원어 사전 등록 중단 · 신규 ${imported.toLocaleString()}건까지 저장 · ${e.message}`}finally{updateLexiconImportButton()}}
async function syncOriginalReference(showGuide=false){const reference=$('oReference').value.trim()||$('reference').value.trim();if(!reference)return null;try{const r=await fetch('/api/reference-info?reference='+encodeURIComponent(reference)),d=await r.json();if(!r.ok)throw new Error(d.detail||'성경 참조 형식 확인 필요');$('oReference').value=d.reference||reference;if(d.primary_original_language)$('oLanguage').value=d.primary_original_language;if(showGuide){const language=d.primary_original_language==='grc'?'신약 · 헬라어(grc)':d.primary_original_language==='he'?'구약 · 히브리어(he)':'원어 언어 직접 확인';$('originalMessage').textContent=d.is_range?`${d.reference} · ${language} · 범위는 조회용입니다. 직접 추가하려면 한 절을 입력하세요.`:`${d.reference} · ${language} · 직접 추가 가능한 한 절 참조입니다.`}return d}catch(e){if(showGuide)$('originalMessage').textContent='성경 참조 확인: '+e.message;return null}}
$('loadOriginal').onclick=loadOriginalNotes;$('checkOriginalCoverage').onclick=()=>checkOriginalCoverage(true);
$('addOriginal').onclick=async()=>{const info=await syncOriginalReference(false);const reference=$('oReference').value.trim()||$('reference').value.trim();if(!reference){$('originalMessage').textContent='성경 참조를 입력하세요.';return}if(!info){$('originalMessage').textContent='성경 참조 형식을 먼저 확인하세요. 예: MAT 14:27';return}if(info.is_range){$('originalMessage').textContent=`${info.reference}은 범위 조회용입니다. '이 본문 원어 근거 보기'를 사용하거나 직접 추가할 한 절(예: ${info.first_reference})을 입력하세요.`;return}const p={reference:info.reference,language:$('oLanguage').value,lemma:$('oLemma').value.trim(),transliteration:$('oTransliteration').value,gloss:$('oGloss').value,morphology:$('oMorphology').value,source:$('oSource').value,license_note:$('oLicense').value};if(!p.lemma){$('originalMessage').textContent='직접 추가하려면 원어/lemma가 필요합니다. 이미 등록된 SBLGNT/원어 자료를 찾으려면 오른쪽의 원어 근거 보기를 누르세요.';return}const r=await fetch('/api/original-notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}),d=await r.json();$('originalMessage').textContent=r.ok?'원어 근거가 저장되었습니다.':(d.detail||'저장 실패');if(r.ok)loadOriginalNotes()};
async function loadOriginalNotes(){let reference=$('oReference').value.trim()||$('reference').value.trim();if(!reference){$('originalMessage').textContent='성경 참조를 입력하세요.';return}const info=await syncOriginalReference(false);if(!info){$('originalMessage').textContent='성경 참조 형식을 확인하세요. 예: MAT 14:27-31';return}reference=info.reference;const r=await fetch('/api/original-notes?reference='+encodeURIComponent(reference)),d=await r.json();if(!r.ok){$('originalMessage').textContent=d.detail||'원어 근거 조회 실패';return}const enriched=(d.items||[]).filter(n=>n.lexicon_enriched).length;$('originalResults').innerHTML=d.items.length?d.items.map(n=>`<article class="compare-card"><strong>${esc(n.reference)} · ${esc(n.language)} · ${esc(n.lemma)}</strong><p>음역: ${esc(n.transliteration||'미기록')}<br>뜻: ${esc(n.gloss||'미기록')}<br>형태: ${esc(n.morphology||'미기록')}</p><small>원문 근거: ${esc(n.source)} · ${esc(n.license_note)}</small>${n.lexicon_enriched?`<br><small>사전 보강: ${esc(n.lexicon_source)} · ${esc(n.lexicon_license_note)}</small>`:''}</article>`).join(''):'<p>등록된 원어 근거가 없습니다.</p>';$('originalMessage').textContent=d.items.length?`${reference} 범위 포함 원어 근거 ${d.items.length}건 · ${info.primary_original_language==='grc'?'헬라어 우선':'히브리어 우선'}${enriched?` · 사전 보강 ${enriched}건`:''}`:`${reference}에 등록된 원어 근거가 없습니다. 아래 '원어 근거 파일 일괄 가져오기'에서 출처·사용조건을 확인한 SBLGNT/형태론 자료를 먼저 등록하세요.`}
