async function refreshSaved(){const r=await fetch('/api/sermons/saved'),d=await r.json();$('savedSermons').innerHTML='<option value="">저장된 설교 선택</option>'+d.items.map(x=>`<option value="${x.id}">#${x.id} ${esc(x.topic)} · v${x.latest_version}</option>`).join('');loadPreviewOptions()}
async function loadPreviewOptions(){const select=$('previewVersions'),status=$('previewStatus');if(!select)return;select.innerHTML='<option value="">최종 잠금본을 확인하는 중입니다…</option>';select.disabled=true;previewItems=[];previewMode='';try{const sermons=await (await fetch('/api/sermons/saved',{cache:'no-store'})).json();for(const sermon of sermons.items||[]){const versions=await (await fetch(`/api/sermons/${sermon.id}/versions`,{cache:'no-store'})).json();for(const version of versions.items||[]){const review=await (await fetch(`/api/sermons/${sermon.id}/versions/${version.version}/reviews`,{cache:'no-store'})).json();if(review.locked&&review.lock?.integrity_ok)previewItems.push({...version,sermon_id:sermon.id,topic:sermon.topic,review})}}const draftOption=currentText.trim()?'<option value="draft">현재 생성된 설교 초안 · 검토용</option>':'';select.innerHTML=(previewItems.length?'<option value="">최종 잠금본 선택</option>'+previewItems.map((x,i)=>`<option value="${i}">${esc(x.topic)} · v${x.version} · ${esc(x.created_at)}</option>`).join(''):'<option value="">최종 잠금된 설교가 없습니다</option>')+draftOption;select.disabled=!(previewItems.length||currentText.trim());status.textContent=currentText.trim()?'현재 생성된 설교 초안도 예외적으로 검토할 수 있습니다. 초안은 승인·잠금 전까지 다운로드/인쇄할 수 없습니다.':previewItems.length?'최종 잠금본을 선택한 뒤 미리보기를 열어 확인하세요.':'승인 후 최종 잠금된 설교가 아직 없습니다.';$('loadPreview').disabled=!(previewItems.length||currentText.trim());['previewMarkdown','previewHtml','previewPdf','previewHwpx','printPreview'].forEach(id=>$(id).disabled=true)}catch(e){select.innerHTML='<option value="">미리보기 목록을 불러오지 못했습니다</option>';status.textContent='최종 잠금본 확인 실패 · '+e.message}}
function selectedPreviewItem(){const value=$('previewVersions').value;return value==='draft'?null:previewItems[Number(value)]||null}
function openSermonPreview(){const draft=$('previewVersions').value==='draft',item=selectedPreviewItem();if(!draft&&!item){$('previewStatus').textContent='미리 볼 최종 잠금본 또는 현재 생성 초안을 선택하세요.';return}const meta=draft?(currentData||{}):(item.metadata||{});previewMode=draft?'draft':'locked';$('previewLabel').textContent=draft?'DRAFT PREVIEW · REVIEW ONLY':'FINAL SERMON PREVIEW · APPROVED';$('previewHeading').textContent=draft?(meta.topic||$('topic').value||'제목 없음'):(item.topic||meta.topic||'제목 없음');$('previewMeta').textContent=[meta.main_reference?'중심본문 '+meta.main_reference:'',meta.target_minutes?`${meta.target_minutes}분`:'',draft?'검토용 초안 · 최종 잠금 전':`버전 v${item.version} · 잠금 담당자 ${item.review.lock.locked_by}`].filter(Boolean).join(' · ');$('previewContent').textContent=draft?currentText:(item.content||'');$('sermonPreview').hidden=false;$('previewStatus').textContent=draft?'검토용 초안입니다. 최종 승인·잠금 전이므로 다운로드, 인쇄, 배포 기능은 잠겨 있습니다.':'무결성이 확인된 최종 잠금본입니다. 배포·출력 전에 내용을 확인하세요.';['previewMarkdown','previewHtml','previewPdf','previewHwpx','printPreview'].forEach(id=>$(id).disabled=draft)}
function downloadPreview(format){const item=selectedPreviewItem();if(previewMode==='draft'||!item){alert('검토용 초안은 최종 승인·잠금 후에만 다운로드할 수 있습니다.');return}if(format==='hwpx'){downloadExport(`/api/sermons/${item.sermon_id}/versions/${item.version}/export-hwpx`,{});return}const meta={...(item.metadata||{}),topic:item.topic,sermon_id:item.sermon_id,version:item.version,review_state:item.review};const endpoints={markdown:'/api/export/markdown',html:'/api/export/html',pdf:'/api/export/pdf'};downloadExport(endpoints[format],format==='markdown'?{text:item.content}:{text:item.content,meta,sources:meta.sources||[]})}
function printSermonPreview(){if($('sermonPreview').hidden)return;if(previewMode==='draft'){alert('검토용 초안은 최종 승인·잠금 후에만 인쇄할 수 있습니다.');return}const node=$('sermonPrintDocument'),previewPanel=$('previewPanel');node.innerHTML='';const title=document.createElement('h1');title.textContent=$('previewHeading').textContent;const meta=document.createElement('p');meta.className='print-meta';meta.textContent=$('previewMeta').textContent;const content=document.createElement('div');content.className='print-content';content.textContent=$('previewContent').textContent;const footer=document.createElement('p');footer.className='print-footer';footer.textContent='LM Studio 로컬 AI · 목회자 승인 최종 잠금본';node.append(title,meta,content,footer);document.body.appendChild(node);document.body.classList.add('print-preview');const restore=()=>{document.body.classList.remove('print-preview');node.innerHTML='';previewPanel.appendChild(node);window.removeEventListener('afterprint',restore)};window.addEventListener('afterprint',restore);window.print();setTimeout(restore,1000)}
async function loadVersions(){const id=$('savedSermons').value;if(!id)return;const r=await fetch(`/api/sermons/${id}/versions`),d=await r.json();loadedVersions=d.items;const opts='<option value="">버전 선택</option>'+d.items.map(v=>`<option value="${v.version}">v${v.version} · ${esc(v.created_at)}</option>`).join('');$('versionA').innerHTML=opts;$('versionB').innerHTML=opts;await loadProjectMeta(id)}
async function loadSelectedVersion(v){if(!v)return;const item=loadedVersions.find(x=>String(x.version)===String(v));if(!item)return;invalidatePreflight('저장된 설교의 입력값을 불러왔습니다. 다시 생성하려면 최종 점검을 실행하세요.');currentText=item.content;currentData=item.metadata||{};currentSermonId=Number($('savedSermons').value);currentVersion=Number(v);$('output').textContent=currentText;$('topic').value=currentData.topic||$('topic').value;$('details').value=currentData.details||'';$('reference').value=currentData.main_reference||'';$('studyReference').value=currentData.main_reference||'';$('compareReference').value=currentData.main_reference||'';$('oReference').value=currentData.main_reference||'';if(currentData.audience)$('audience').value=currentData.audience;if(currentData.tradition)$('tradition').value=currentData.tradition;if(currentData.target_minutes||currentData.minutes)$('minutes').value=String(currentData.target_minutes||currentData.minutes);currentStudy=currentData.study_note&&typeof currentData.study_note==='object'?currentData.study_note:null;if(currentStudy){renderStudyNote(currentStudy);$('copyStudy').disabled=!currentStudy.note_markdown}else{clearStudyView()}currentOutline=currentData.outline&&typeof currentData.outline==='object'?currentData.outline:null;if(currentOutline)renderOutline(currentOutline);else clearOutlineView();renderAudit(currentData.audit);renderCitation(currentData.citation_analysis||currentData.audit?.citation_analysis);await loadReviewState();await loadRevisionSuggestions();await loadWorkflowStatus(currentSermonId,currentVersion);['export','exportHtml','exportWord','exportPdf','saveSermon'].forEach(id=>$(id).disabled=false)}
function pageFormatOptions(){return{profile:$('pageFormatProfile')?.value||'',theme:$('pageFormatTheme')?.value||'default',preset:$('pageFormatPreset')?.value||''}}
async function compareVersions(){const id=$('savedSermons').value,a=$('versionA').value,b=$('versionB').value;if(!id||!a||!b)return;const r=await fetch(`/api/sermons/${id}/diff?a=${a}&b=${b}`),d=await r.json();$('versionDiff').textContent=r.ok?(d.diff||'두 버전의 텍스트 차이가 없습니다.'):(d.detail||'비교 실패')}
