function exportGroundingReport(format){if(!currentData?.grounding_audit){alert('Grounding 검증 결과가 없어 보고서를 만들 수 없습니다.');return}downloadExport('/api/export/grounding',{format,meta:currentData,sources:currentData.sources||[]})}
$('exportGroundingHtml').onclick=()=>exportGroundingReport('html');$('exportGroundingMd').onclick=()=>exportGroundingReport('markdown');
if(window.GROUNDING_DASHBOARD_ENABLED&&window.GROUNDING_REPORT_EXPORT_ENABLED){$('exportGroundingHtml').hidden=false;$('exportGroundingMd').hidden=false}
async function downloadExport(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(r.ok)location.href=d.url;else alert(d.detail||'저장 실패')}
$('compareBtn').onclick=async()=>{const ref=$('compareReference').value.trim();if(!ref)return;const r=await fetch('/api/compare?reference='+encodeURIComponent(ref)),d=await r.json();$('compareResults').innerHTML=d.items.length?d.items.map(x=>`<article class="compare-card"><strong>${esc(x.translation)}</strong> <small>${esc(x.language)}</small><p>${esc(x.text)}</p><small>${esc(x.license_note||'사용조건 기록 없음')}</small></article>`).join(''):'<p>같은 참조로 등록된 자료가 없습니다.</p>'};
$('addPassage').onclick=async()=>{const p={translation:$('pTranslation').value,language:$('pLanguage').value||'ko',reference:$('pReference').value,text:$('pText').value,license_note:$('pLicense').value};if(!p.translation||!p.reference||!p.text){$('addMessage').textContent='번역/자료명, 참조, 본문은 필수입니다.';return}const r=await fetch('/api/passages',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(p)}),d=await r.json();$('addMessage').textContent=r.ok?'저장되었습니다.':(d.detail||'저장에 실패했습니다.');if(r.ok)checkHealth()};
function renderGroundingDashboard(audit){const box=$('groundingDashboard'),summary=$('groundingSummary'),details=$('groundingDetails');if(!box||!summary||!details)return;if(!window.GROUNDING_DASHBOARD_ENABLED){box.hidden=true;return}box.hidden=false;if(!audit){summary.textContent='설교문 근거 검증: 사용 안 함 또는 기록 없음';details.innerHTML='';return}const total=Number(audit.auditable_claims||0),coverage=total?Math.round(Number(audit.grounding_coverage||0)*100):0;summary.innerHTML=`<div class="grounding-stats"><span>✓ 근거 확인 <b>${Number(audit.grounded||0)}</b></span><span>△ 부분 확인 <b>${Number(audit.partially_grounded||0)}</b></span><span>! 확인 필요 <b>${Number(audit.ungrounded||0)}</b></span><span>근거 연결률 <b>${coverage}%</b></span></div><small>생성된 검증 대상 주장 중 등록 근거와 연결된 비율입니다. 최종 해석 책임을 대신하지 않습니다.</small>`;details.innerHTML=`<details><summary>상세 검증 보기</summary>${(audit.results||[]).slice(0,10).map(x=>`<div class="grounding-claim"><b>${esc(x.status)}</b> · ${esc(x.reason)}</div>`).join('')}</details>`}
function updateWizardEvidenceSummary(audit){const badge=$('wizardEvidenceBadge'),coverage=$('wizardEvidenceCoverage'),issues=$('wizardEvidenceIssues'),web=$('wizardWebEvidence'),hint=$('wizardEvidenceHint');if(!badge||!coverage||!issues||!web||!hint)return;const grounding=window.currentGroundingAudit||currentData?.grounding_audit||null;if(!audit&&!grounding){badge.textContent='확인 전';badge.className='evidence-badge';coverage.textContent='-';issues.textContent='-';web.textContent='사용 안 함';hint.textContent='설교를 생성하면 Bible Evidence와 Grounding Audit 결과가 여기에 표시됩니다.';return}const total=Number(grounding?.auditable_claims||0),rate=total?Math.round(Number(grounding.grounding_coverage||0)*100):0;coverage.textContent=`${rate}%`;issues.textContent=String(Number(grounding?.ungrounded||0));const webCount=(currentData?.web_grounding?.evidence||[]).length;web.textContent=webCount?`${webCount}건 사용`:'사용 안 함';const blocked=audit?.status==='blocked';badge.textContent=blocked?'확인 필요':grounding?'검증 완료':'감사 기록 있음';badge.className='evidence-badge '+(blocked?'warn':'ready');hint.textContent=blocked?'자동 점검 경고가 있어 상세 Audit을 확인하세요.':'상세 근거 연결과 Claim별 결과는 결과 패널에서 확인할 수 있습니다.'}
function renderAudit(audit){const box=$('auditBox');renderQuality(audit?.post_generation_quality||audit?.evidence?.post_generation_quality);renderGroundingDashboard(window.currentGroundingAudit||currentData?.grounding_audit||null);updateWizardEvidenceSummary(audit);if(!audit){box.className='audit-box neutral';box.textContent='이 버전에 연결된 감사 기록이 없습니다.';return}const labels={ready_for_review:'검토 가능',needs_review:'확인 필요',blocked:'차단'};box.className='audit-box '+audit.status;box.innerHTML=`<strong>생성 감사 #${esc(audit.id)} · ${esc(labels[audit.status]||audit.status)}</strong><br>${audit.warnings?.length?audit.warnings.map(esc).join(' · '):'자동 점검 경고 없음 · 목회자 최종 검토는 별도 필요'}`}
function renderQuality(data){const summary=$('qualitySummary'),checks=$('qualityChecks'),issues=$('qualityIssues');if(!summary||!checks||!issues)return;if(!data?.checks){summary.textContent='이 버전에는 생성후 품질검사 기록이 없습니다. 저장 버전은 재감사하면 최신 검사 기준이 적용됩니다.';checks.innerHTML='';issues.innerHTML='';return}summary.textContent=data.status==='pass'?`자동 확인 가능한 ${Number(data.checks.length)}개 영역을 통과했습니다. 목회자의 신학적·목회적 최종 검토는 별도입니다.`:`자동 점검에서 확인할 항목 ${Number(data.issue_count||0)}건을 찾았습니다.`;checks.innerHTML=data.checks.map(x=>`<div class="quality-check ${x.state==='pass'?'pass':'warn'}"><b>${esc(x.label)}</b><span>${x.state==='pass'?'통과':`확인 ${Number(x.issue_count||0)}건`}</span></div>`).join('');issues.innerHTML=(data.issues||[]).slice(0,30).map(x=>`<div class="quality-issue"><b>${x.sentence?`문장 ${Number(x.sentence)} · `:''}${esc(x.reason)}</b>${x.text?`<br>${esc(x.text)}`:''}</div>`).join('')}
function renderCitation(data){const summary=$('citationSummary'),results=$('citationResults');if(!data){summary.textContent='이 버전에 문장별 근거 분석 기록이 없습니다. 저장 버전은 재감사할 수 있습니다.';results.innerHTML='';return}summary.innerHTML=`전체 ${Number(data.sentence_count||0)}문장 · 명시 근거 연결 <b>${Number(data.mapped_count||0)}건</b> · 근거 확인 필요 <b>${Number(data.unsupported_count||0)}건</b>`;const unsupported=(data.unsupported_claims||[]).slice(0,20).map(x=>`<div class="citation-entry unsupported"><b>문장 ${x.sentence} · 확인 필요</b> · ${esc(x.reason)}<br>${esc(x.text)}</div>`);const mapped=(data.mappings||[]).slice(0,20).map(x=>`<div class="citation-entry"><b>문장 ${x.sentence} · ${esc((x.references||[]).join(', '))}</b><br>${esc(x.text)}</div>`);results.innerHTML=[...unsupported,...mapped].join('')||'<div class="citation-entry">표시할 근거 연결 문장이 없습니다.</div>'}
async function loadReviewState(){const id=$('savedSermons').value,v=$('versionA').value;if(!id||!v){$('reviewState').textContent='저장된 설교와 버전 A를 선택하세요.';$('finalPackage').disabled=true;return}const r=await fetch(`/api/sermons/${id}/versions/${v}/reviews`),d=await r.json();if(!r.ok){$('reviewState').textContent=d.detail||'검토 이력 조회 실패';$('finalPackage').disabled=true;return}const outputIsSelected=currentSermonId===Number(id)&&currentVersion===Number(v);if(outputIsSelected&&currentData){currentData.review_state=d;currentData.audit=d.audit;currentData.audit_id=d.audit?.id||null;currentData.citation_analysis=d.audit?.citation_analysis||null;renderAudit(d.audit);renderCitation(d.audit?.citation_analysis)}const labels={unreviewed:'미검토',comment:'댓글',changes_requested:'변경 요청',approved:'승인',locked:'최종 잠금'};const lockText=d.lock?` · <span class="lock-ok">최종 잠금: ${esc(d.lock.locked_by)} · 무결성 ${d.lock.integrity_ok?'정상':'확인 필요'}</span>`:'';$('reviewState').innerHTML=`<strong>현재 상태: ${esc(labels[d.state]||d.state)}</strong> · 감사: ${esc(d.audit?.status||'없음')}${lockText}<div class="review-history">${d.history.length?d.history.map(x=>`<div class="review-entry"><b>${esc(x.reviewer)}</b> · ${esc(labels[x.status]||x.status)} · ${esc(x.created_at)}<br>${esc(x.comment||'의견 없음')}</div>`).join(''):'검토 기록이 없습니다.'}</div>`;$('submitReview').disabled=!!d.locked;$('reauditVersion').disabled=!!d.locked||!!d.approved;$('lockVersion').disabled=!!d.locked;$('generateSuggestions').disabled=!!d.locked||!!d.approved;$('applySuggestions').disabled=!!d.locked||!!d.approved;$('finalPackage').disabled=!(d.locked&&d.lock?.integrity_ok)}
async function submitReview(){const id=$('savedSermons').value,v=$('versionA').value;if(!id||!v){alert('저장된 설교와 버전 A를 선택하세요.');return}const body={reviewer:$('reviewer').value.trim(),status:$('reviewStatus').value,comment:$('reviewComment').value};if(!body.reviewer){alert('검토자 이름을 입력하세요.');return}const r=await fetch(`/api/sermons/${id}/versions/${v}/reviews`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok){alert(d.detail||'검토 기록 실패');return}$('reviewComment').value='';await loadReviewState();loadProjectDashboard();loadWorkflowStatus(Number(id),Number(v))}
async function reauditVersion(){const id=$('savedSermons').value,v=$('versionA').value;if(!id||!v){alert('저장된 설교와 버전 A를 선택하세요.');return}const r=await fetch(`/api/sermons/${id}/versions/${v}/reaudit`,{method:'POST'}),d=await r.json();if(!r.ok){alert(d.detail||'재감사 실패');return}if(currentSermonId===Number(id)&&currentVersion===Number(v)&&currentData){currentData.audit=d.audit;currentData.audit_id=d.audit.id;currentData.citation_analysis=d.citation_analysis;renderAudit(d.audit);renderCitation(d.citation_analysis)}await loadReviewState();loadProjectDashboard();loadWorkflowStatus(Number(id),Number(v));alert('선택 버전의 재감사가 완료되었습니다.')}
async function lockVersion(){const id=$('savedSermons').value,v=$('versionA').value,locked_by=$('reviewer').value.trim();if(!id||!v){alert('저장된 설교와 버전 A를 선택하세요.');return}if(!locked_by){alert('검토자/잠금 담당자 이름을 입력하세요.');return}if(!confirm('이 승인본을 최종 잠금하시겠습니까? 잠금 후에는 재감사와 검토 상태 추가가 차단됩니다.'))return;const r=await fetch(`/api/sermons/${id}/versions/${v}/lock`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({locked_by})}),d=await r.json();if(!r.ok){alert(d.detail||'최종 잠금 실패');return}await loadReviewState();loadProjectDashboard();loadWorkflowStatus(Number(id),Number(v));alert('승인본이 최종 잠금되었습니다.')}
function renderRevisionSuggestions(items){const box=$('suggestionResults');if(!items?.length){box.innerHTML='<div class="suggestion-card">저장된 수정 제안이 없습니다.</div>';return}box.innerHTML=items.slice().reverse().map(x=>`<article class="suggestion-card ${esc(x.status)}"><div class="suggestion-head"><label>${x.status==='pending'?`<input class="revision-check" type="checkbox" value="${Number(x.id)}">`:''}<b>문장 ${Number(x.sentence_no)} · ${esc(x.status)}</b></label><small>${esc((x.references||[]).join(', '))}</small></div><div class="before-after"><div><b>수정 전</b><br>${esc(x.original_text)}</div><div class="after"><b>제안문</b><br>${esc(x.proposed_text)}</div></div><small>이유: ${esc(x.rationale||'기록 없음')}${x.applied_version?` · 반영된 버전 v${Number(x.applied_version)}`:''}</small></article>`).join('')}
async function loadRevisionSuggestions(){const id=$('savedSermons').value,v=$('versionA').value;if(!id||!v){$('suggestionMessage').textContent='저장된 설교와 버전 A를 선택하세요.';$('suggestionResults').innerHTML='';return}const r=await fetch(`/api/sermons/${id}/versions/${v}/revision-suggestions`),d=await r.json();if(!r.ok){$('suggestionMessage').textContent=d.detail||'수정 제안 조회 실패';return}const pending=(d.items||[]).filter(x=>x.status==='pending').length;$('suggestionMessage').textContent=`저장된 제안 ${d.items.length}건 · 선택 반영 가능 ${pending}건`;renderRevisionSuggestions(d.items)}
async function generateRevisionSuggestions(){const id=$('savedSermons').value,v=$('versionA').value;if(!id||!v){alert('저장된 설교와 버전 A를 선택하세요.');return}const btn=$('generateSuggestions');btn.disabled=true;$('suggestionMessage').textContent='LM Studio가 등록된 성경 근거 안에서 수정 제안을 만들고 있습니다…';try{const r=await fetch(`/api/sermons/${id}/versions/${v}/revision-suggestions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:$('model').value})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'수정 제안 생성 실패');$('suggestionMessage').textContent=`${d.message} · 검증 탈락 ${Number(d.invalid_count||0)}건`;renderRevisionSuggestions(d.items)}catch(e){$('suggestionMessage').textContent='오류: '+e.message}finally{btn.disabled=false;await loadReviewState()}}
async function applySelectedSuggestions(){const id=$('savedSermons').value,v=$('versionA').value;const ids=[...document.querySelectorAll('.revision-check:checked')].map(x=>Number(x.value));if(!id||!v){alert('저장된 설교와 버전 A를 선택하세요.');return}if(!ids.length){alert('반영할 제안을 하나 이상 선택하세요.');return}if(!confirm(`선택한 ${ids.length}개 제안을 새 버전에 반영하시겠습니까? 기존 버전은 변경되지 않습니다.`))return;const r=await fetch(`/api/sermons/${id}/versions/${v}/apply-revisions`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({suggestion_ids:ids})}),d=await r.json();if(!r.ok){alert(d.detail||'제안 반영 실패');return}await refreshSaved();$('savedSermons').value=String(id);await loadVersions();$('versionA').value=String(d.version);await loadSelectedVersion(d.version);loadProjectDashboard();alert(`선택 제안을 새 버전 v${d.version}에 반영하고 재감사했습니다.`)}
async function saveManualRevision(){const id=$('savedSermons').value,v=$('versionA').value,content=$('manualRevisionContent').value.trim();if(!id||!v){$('manualRevisionMessage').textContent='먼저 저장된 설교와 버전을 선택하세요.';return}if(!content){$('manualRevisionMessage').textContent='수정할 설교문이 비어 있습니다.';return}if(!confirm('수동 수정본을 기존 버전과 분리된 새 버전으로 저장하고 재감사하시겠습니까?'))return;const button=$('saveManualRevision');button.disabled=true;$('manualRevisionMessage').textContent='기존 버전을 보존하고 새 수정 버전을 저장·재감사하고 있습니다…';try{const metadata={...(currentData||{}),audit_id:null,audit:null,citation_analysis:null,review_state:null,revision_parent_version:Number(v),revision_method:'manual'};const r=await fetch('/api/sermons/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic:$('topic').value||'제목 없음',content,metadata,sermon_id:Number(id)})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'수동 수정본 저장 실패');const auditResponse=await fetch(`/api/sermons/${id}/versions/${d.version}/reaudit`,{method:'POST'}),auditData=await auditResponse.json();if(!auditResponse.ok)throw new Error(auditData.detail||'새 버전 재감사 실패');await refreshSaved();$('savedSermons').value=String(id);await loadVersions();$('versionA').value=String(d.version);await loadSelectedVersion(d.version);$('manualRevisionMessage').textContent=`수동 수정본 v${d.version} 저장·재감사 완료 · 승인 전 검토가 필요합니다.`;loadProjectDashboard()}catch(e){$('manualRevisionMessage').textContent='오류: '+e.message}finally{button.disabled=false}}
async function loadReadingSpeed(){const r=await fetch('/api/settings/reading-speed'),d=await r.json();if(r.ok)$('readingCpm').value=d.chars_per_minute}
async function saveReadingSpeed(){const value=Number($('readingCpm').value);const r=await fetch('/api/settings/reading-speed',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({chars_per_minute:value})}),d=await r.json();if(!r.ok){alert(d.detail||'낭독속도 저장 실패');return}$('readingCpm').value=d.chars_per_minute;alert(`${d.chars_per_minute}자/분으로 저장했습니다.`);loadProjectDashboard()}
async function calibrateReadingSpeed(){const body={text:$('calibrationText').value,seconds:Number($('calibrationSeconds').value)};const r=await fetch('/api/settings/reading-speed/calibrate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok){alert(d.detail||'낭독속도 보정 실패');return}$('readingCpm').value=d.chars_per_minute;alert(`실제 낭독 기준 ${d.chars_per_minute}자/분으로 보정했습니다.`);loadProjectDashboard()}
async function loadProjectDashboard(){const r=await fetch('/api/projects/dashboard'),d=await r.json();if(!r.ok)return;const labels={total:'전체',unreviewed:'미검토',changes_requested:'변경 요청',approved:'승인',locked:'최종 잠금'};const summary=d.summary||{};if($('wizardProjectTotal'))$('wizardProjectTotal').textContent=`${Number(summary.total||0)}개`;if($('wizardProjectReview'))$('wizardProjectReview').textContent=String(Number(summary.unreviewed||0)+Number(summary.changes_requested||0));if($('wizardProjectLocked'))$('wizardProjectLocked').textContent=String(Number(summary.locked||0));if($('wizardProjectHint'))$('wizardProjectHint').textContent=summary.total?`최근 프로젝트 ${d.projects?.[0]?.topic?`“${d.projects[0].topic}” · `:''}저장·검토 상태를 상세 패널에서 확인할 수 있습니다.`:'아직 저장된 설교가 없습니다. 초안을 생성한 뒤 버전 저장을 시작하세요.';$('projectSummary').innerHTML=['total','unreviewed','changes_requested','approved','locked'].map(k=>`<div class="project-stat"><small>${labels[k]}</small><b>${Number(summary[k]||0)}</b></div>`).join('');const stateLabels={unreviewed:'미검토',comment:'검토 중',changes_requested:'변경 요청',approved:'승인',locked:'최종 잠금'};$('projectDashboard').innerHTML=d.projects.length?d.projects.map(p=>`<article class="project-card"><header><h3>${esc(p.topic)}</h3><span class="state">${esc(stateLabels[p.state]||p.state)}</span></header><p>${esc(p.service_date||'예배일 미정')} · ${esc(p.series_name||'시리즈 없음')} · v${Number(p.latest_version)}</p><small>목표 ${Number(p.target_minutes)}분 · 예상 ${Number(p.minutes_estimate)}분 · ${Number(p.reading_cpm)}자/분 · 감사 ${esc(p.audit_status)}</small><div class="history-row"><button onclick="openProject(${Number(p.sermon_id)},${Number(p.latest_version)})">프로젝트 열기</button></div></article>`).join(''):'<div class="project-card">아직 저장된 설교 프로젝트가 없습니다.</div>'}
async function loadProjectMeta(id){const r=await fetch(`/api/projects/${id}`),d=await r.json();if(!r.ok)return;$('serviceDate').value=d.service_date||'';$('seriesName').value=d.series_name||'';$('preacher').value=d.preacher||'';$('projectNotes').value=d.notes||''}
async function saveProjectMeta(){const id=$('savedSermons').value;if(!id){alert('저장된 설교 프로젝트를 먼저 선택하세요.');return}const body={service_date:$('serviceDate').value,series_name:$('seriesName').value,preacher:$('preacher').value,notes:$('projectNotes').value};const r=await fetch(`/api/projects/${id}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();if(!r.ok){alert(d.detail||'프로젝트 정보 저장 실패');return}alert('프로젝트 정보를 저장했습니다.');loadProjectDashboard()}
