async function buildStudyNote(){const reference=$('studyReference').value.trim()||$('reference').value.trim();if(!reference){alert('연구할 중심본문을 입력하세요.');return}if($('reference').value.trim()!==reference)invalidatePreflight('연구할 중심본문으로 설교 요청 본문이 변경되었습니다. 최종 점검을 다시 실행하세요.');$('studyReference').value=reference;$('reference').value=reference;$('compareReference').value=reference;$('oReference').value=reference;const model=$('embeddingModel').value;const params=new URLSearchParams({reference});if(model)params.set('model',model);$('studyStatus').textContent='등록 번역본·원어·문맥 자료를 확인하고 있습니다…';try{const r=await fetch('/api/study?'+params.toString()),d=await r.json();if(!r.ok)throw new Error(d.detail||'본문 연구 실패');currentStudy=d;renderStudyNote(d);$('copyStudy').disabled=false}catch(e){currentStudy=null;$('copyStudy').disabled=true;$('studyStatus').textContent='오류: '+e.message}}
function renderInterpretationFlow(flow){const box=$('interpretationFlow');if(!box)return;box.innerHTML=(flow||[]).length?(flow||[]).map(x=>`<div class="flow-stage ${x.ready?'ready':'missing'}"><b>${esc(x.label)}</b><small>${esc(x.ready?((x.sources||[]).join(', ')||x.status):x.status)}</small><span>${esc(x.purpose||'')}</span></div>`).join(''):'<div class="flow-stage missing"><b>자료 확인 필요</b><small>통합 근거 패킷을 다시 검사하세요.</small></div>'}
function renderTranslationPolicy(policy){const summary=$('translationPolicySummary'),groups=$('translationPolicyGroups');if(!summary||!groups)return;if(!policy){summary.textContent='핵심 엔진과 보조 번역의 역할을 아직 검사하지 않았습니다.';groups.innerHTML='';return}const missing=policy.missing_core||[];summary.className='notice '+(policy.core_engine_ready?'policy-ok':'policy-warn');summary.textContent=policy.core_engine_ready?'핵심 엔진 준비 완료 · 개역개정·원문·ESV·NASB·NIV·CSB·NET':'핵심 엔진 보완 권장 · 미등록: '+(missing.join(', ')||'재검사 필요');groups.innerHTML=(policy.groups||[]).map(x=>`<div class="translation-policy-card ${esc(x.key)}"><b>${esc(x.label)}</b><small>${esc((x.sources||[]).join(', ')||'등록 자료 없음')}</small><span>${esc(x.purpose||'')}</span></div>`).join('')+`<div class="translation-policy-card guard"><b>AMP · The Message 제한</b><small>${esc((policy.expression_only_sources||[]).join(', ')||'현재 등록 없음')}</small><span>${esc(policy.guardrail||'표현 이해 보조자료로만 사용합니다.')}</span></div>`}
function renderSocialPolicy(policy){const status=$('socialPolicyStatus'),lenses=$('socialPolicyLenses'),rules=$('socialPolicyRules');if(!status||!lenses||!rules)return;if(!policy){status.textContent='공의·사랑·화해·책임의 중립 적용 원칙을 아직 검사하지 않았습니다.';lenses.innerHTML='';rules.innerHTML='';return}status.className='notice policy-ok';status.textContent=policy.active?'사회·정치·세계정세 입력 감지 · 중립성 가드가 적용됩니다.':'항상 적용 · 구체적인 시대 상황을 다룰 때 자동으로 강화됩니다.';lenses.innerHTML=(policy.biblical_lenses||[]).map(x=>`<span>${esc(x.label)}</span>`).join('');rules.innerHTML=(policy.rules||[]).map(x=>`<div>${esc(x)}</div>`).join('')+`<small>${esc(policy.notice||'')}</small>`}
async function buildEvidencePacket(){
  const reference=$('studyReference').value.trim()||$('reference').value.trim();
  if(!reference){alert('중심본문을 먼저 입력하세요.');return}
  const body={topic:$('topic').value.trim(),details:$('details').value,main_reference:reference,tradition:$('tradition').value,embedding_model:$('embeddingModel').value,use_rag:$('useRag').checked},btn=$('buildEvidencePacket');
  btn.disabled=true;$('evidencePacketStatus').className='import-status';$('evidencePacketStatus').textContent='근거 품질 가드로 중심본문 연속성·원어 출처·교리 전통을 검사하고 있습니다…';
  try{
    const r=await fetch('/api/research/packet',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();
    if(!r.ok)throw new Error(d.detail||'통합 근거 검사 실패');
    currentEvidencePacket=d;currentStudy=d.study||currentStudy;
    const c=d.counts||{},ready=d.readiness||{},quality=d.evidence_completeness||{},alignment=d.doctrine_alignment||{};
    $('evidencePacketStatus').className='import-status '+(ready.generation_ready?'ok':'bad');
    $('evidencePacketStatus').textContent=ready.generation_ready?`설교 생성 근거 준비 · 완성도 ${Number(quality.score||0)}점(${esc(quality.label||'')}) · ${esc(d.search_mode)}`:`설교 생성 보류 · 중심본문 범위 전체를 제공하는 단일 번역/자료가 필요합니다.`;
    $('evidencePacketStats').innerHTML=[['근거 완성도',quality.score],['성경 근거',c.bible_sources],['범위완성 번역',c.complete_translation_sets],['원어 노트',c.original_notes],['교리 근거',c.doctrine_sources]].map(x=>`<div class="study-stat"><small>${esc(x[0])}</small><b>${Number(x[1]||0)}${x[0]==='근거 완성도'?'점':''}</b></div>`).join('');
    renderInterpretationFlow(d.interpretation_flow);
    renderTranslationPolicy(d.translation_policy);
    renderSocialPolicy(d.social_context_policy);
    const checks=[
      [ready.continuous_translation_ready,ready.continuous_translation_ready?`중심본문 연속성 확인 · ${(d.complete_translations||[]).join(', ')}`:'범위 전체를 한 번역/자료로 제공하지 못함'],
      [ready.translation_comparison_ready,ready.translation_comparison_ready?'번역 비교 준비 완료':'번역 비교 자료 2종 미만'],
      [ready.original_language_ready&&!d.original_risk_flags?.length,ready.original_language_ready?(d.original_risk_flags?.length?`원어 근거 주의 ${d.original_risk_flags.length}건`:'원어 출처 가드 통과'):'원어 근거 없음'],
      [ready.doctrine_ready,ready.doctrine_ready?`교리 전통 정합성 확인 · ${esc(alignment.selected_tradition||'공통')}`:'교리 RAG 근거 없음 또는 전통 불일치'],
    ];
    $('evidencePacketWarnings').innerHTML=checks.map(x=>`<div class="evidence-warning ${x[0]?'ok':''}">${esc(x[1])}</div>`).join('')+(d.warnings||[]).slice(0,8).map(x=>`<div class="evidence-warning">${esc(x)}</div>`).join('')+`<div class="evidence-warning ok">${esc(quality.notice||'근거 완성도는 신학적 정확도를 보증하지 않습니다.')}</div>`;
    if(d.study)renderStudyNote(d.study);
  }catch(e){currentEvidencePacket=null;$('evidencePacketStatus').className='import-status bad';$('evidencePacketStatus').textContent='통합 근거 검사 실패 · '+e.message;$('evidencePacketStats').innerHTML='';$('evidencePacketWarnings').innerHTML='';renderInterpretationFlow([]);renderTranslationPolicy(null);renderSocialPolicy(null)}finally{btn.disabled=false}
}
function invalidatePreflight(message='입력 또는 모델 설정이 변경되었습니다. 생성 전 최종 점검을 다시 실행하세요.'){
  lastPreflight=null;$('generate').disabled=true;$('preflightStatus').className='import-status warn';$('preflightStatus').textContent=message;$('preflightSteps').innerHTML='';
}
async function runPreflight(){
  const body={topic:$('topic').value.trim(),details:$('details').value,main_reference:$('reference').value.trim(),tradition:$('tradition').value,minutes:Number($('minutes').value),model:$('model').value,embedding_model:$('embeddingModel').value,use_rag:$('useRag').checked,reading_cpm:Number($('readingCpm').value||330)},btn=$('runPreflight');
  btn.disabled=true;$('generate').disabled=true;$('preflightStatus').className='import-status';$('preflightStatus').textContent='LM Studio · 중심본문 · DB · RAG · 원어 · 교리 · 설교시간을 점검하고 있습니다…';
  try{
    const r=await fetch('/api/preflight',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await r.json();
    if(!r.ok)throw new Error(d.detail||'Preflight 검사 실패');
    lastPreflight=d;const marks={pass:'✓',warn:'!',fail:'×'};
    $('preflightSteps').innerHTML=(d.steps||[]).map(x=>`<div class="preflight-step ${esc(x.state)}"><span class="mark">${marks[x.state]||'?'}</span><b>${esc(x.label)}${x.required?' · 필수':' · 권장'}</b><small>${esc(x.detail)}</small></div>`).join('');
    $('preflightStatus').className='import-status '+(d.ready?'ok':'bad');
    $('preflightStatus').textContent=d.ready?`생성 가능 · 필수조건 통과 · 권장 보완 ${Number(d.warnings||0)}건 · 선택 ${Number(body.minutes)}분`:`생성 차단 · 필수조건 ${Number(d.required_failures||0)}건을 먼저 해결하세요.`;
    $('generate').disabled=!d.ready;
    if(d.packet){currentEvidencePacket=d.packet;currentStudy=d.packet.study||currentStudy;renderInterpretationFlow(d.packet.interpretation_flow);renderTranslationPolicy(d.packet.translation_policy);renderSocialPolicy(d.packet.social_context_policy)}
  }catch(e){lastPreflight=null;$('preflightStatus').className='import-status bad';$('preflightStatus').textContent='Preflight 실패 · '+e.message;$('preflightSteps').innerHTML='';$('generate').disabled=true}finally{btn.disabled=false}
}
function renderLmRecovery(data){const box=$('lmRecoveryStatus');box.className='lm-recovery-status '+(data.ready?'ok':'bad');box.innerHTML=`<b>${esc(data.ready?'연결 복구 완료':'연결 복구 필요')}</b><span>${esc(data.message||'')}</span><div>${(data.steps||[]).map(x=>`<small class="${x.ok?'pass':'fail'}">${x.ok?'✓':'×'} ${esc(x.label)} · ${esc(x.detail)}</small>`).join('')}</div>`}
async function startLmStudioServer(){const btn=$('startLmStudio'),box=$('lmRecoveryStatus');btn.disabled=true;box.className='lm-recovery-status';box.innerHTML='<b>LM Studio Local Server를 확인하고 있습니다…</b><span>이 PC의 lms CLI와 로컬 포트만 사용합니다. 외부 네트워크는 열지 않습니다.</span>';try{const diagResponse=await fetch('/api/lmstudio/diagnostics',{cache:'no-store'}),diag=await apiJson(diagResponse,'LM Studio 진단 실패');if(diag.ok){renderLmRecovery({ready:true,message:diag.message,steps:[{ok:true,label:'Local Server',detail:`${diag.base_url}`},{ok:true,label:'생성 모델',detail:`READY ${Number(diag.generation_models?.length||0)}개`}]});await checkHealth();return}const r=await fetch('/api/lmstudio/start',{method:'POST'}),d=await apiJson(r,'LM Studio 서버 시작 실패');if(!r.ok)throw new Error(d.detail||d.message||'LM Studio 서버 시작 실패');const steps=[{ok:!!d.cli,label:'LM Studio CLI',detail:d.cli||'lms를 찾지 못함'},{ok:!!d.port_open,label:'Local Server',detail:d.port_open?`포트 ${d.port} 열림`:`포트 ${d.port} 닫힘`},{ok:!!d.api_ready,label:'OpenAI 호환 API',detail:d.api_ready?'/v1/models 정상':'API 준비 안 됨'},{ok:(d.generation_models||[]).length>0,label:'생성 모델',detail:(d.generation_models||[]).length?`READY ${(d.generation_models||[]).length}개`:'LM Studio에서 모델 Load 필요'}];renderLmRecovery({ready:!!d.api_ready&&(d.generation_models||[]).length>0,message:d.message,steps});await checkHealth();if(d.api_ready&&(d.generation_models||[]).length)invalidatePreflight('LM Studio 서버가 준비되었습니다. 연결·모델 점검 후 생성 전 최종 점검을 실행하세요.')}catch(e){renderLmRecovery({ready:false,message:e.message,steps:[]})}finally{btn.disabled=false}}
async function recoverLmStudio(){const btn=$('recoverLmStudio'),box=$('lmRecoveryStatus');btn.disabled=true;box.className='lm-recovery-status';box.innerHTML='<b>연결을 다시 확인하고 있습니다…</b><span>Local Server → READY 모델 → 실제 추론 순서로 검사합니다.</span>';try{const selected=$('model').value,r=await fetch('/api/lmstudio/recover',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({model:selected})}),d=await apiJson(r,'LM Studio 연결 복구 점검 실패');if(!r.ok)throw new Error(d.detail||'연결 복구 점검 실패');renderLmRecovery(d);await checkHealth();if(d.ready){if((d.generation_models||[]).includes(d.model))$('model').value=d.model;invalidatePreflight('LM Studio 실제 추론 연결이 복구되었습니다. 생성 전 최종 점검을 다시 실행하세요.')}}catch(e){renderLmRecovery({ready:false,message:e.message,steps:[]})}finally{btn.disabled=false}}
function renderStudyNote(data){const c=data.counts||{};$('studyStatus').textContent=`${esc(data.reference)} · ${data.related_mode==='semantic_rag'?'LM Studio RAG 관련구절 포함':data.related_mode==='index_required'?'RAG 인덱스 필요 · 등록 자료만 정리':'등록 자료 기준 연구 노트'}`+(data.warnings?.length?` · 확인 ${data.warnings.length}건`:' · 근거 구성 확인');$('studyStats').innerHTML=[['번역/본문',c.translations],['원어 노트',c.original_notes],['앞뒤 절',c.context],['관련구절',c.related]].map(x=>`<div class="study-stat"><small>${esc(x[0])}</small><b>${Number(x[1]||0)}</b></div>`).join('');const block=(title,items,render)=>`<section class="study-section"><h4>${title}</h4>${items?.length?items.map(render).join(''):'<div class="study-item">등록 자료 없음</div>'}</section>`;$('studyDashboard').innerHTML=block('번역/본문 비교',data.translations,x=>`<div class="study-item"><b>${esc(x.translation)} · ${esc(x.language)}</b><br>${esc(x.text)}<br><small>${esc(x.license_note||'사용조건 기록 없음')}</small></div>`)+block('히브리어·헬라어',data.original_notes,x=>`<div class="study-item"><b>${esc(x.lemma)}</b> · ${esc(x.transliteration||'사전 음역 미등록')}<br>${x.pronunciations?.length?`<span class="original-pronunciation">원문 · 학술식 독음: ${esc(x.pronunciations.map(p=>p.surface_form+' · '+p.transliteration).join(' / '))}</span><br><small>${esc(x.pronunciations[0].pronunciation_scheme)} · ${esc(x.pronunciations[0].pronunciation_source)}</small><br>`:''}뜻: ${esc(x.gloss||'사전 뜻 미등록')} · 형태/문법: ${esc(x.morphology||'형태·문법 미등록')}<br><small>${esc(x.source||'출처 미기록')} · ${esc(x.license_note||'사용조건 미기록')}</small>${x.lexicon_enriched?`<br><small>사전 보강 출처: ${esc(x.lexicon_source||'출처 미기록')} · ${esc(x.lexicon_license_note||'사용조건 미기록')}</small>`:''}</div>`)+block('앞뒤 절 문맥',data.context,x=>`<div class="study-item"><b>${esc(x.reference)} · ${esc(x.translation)}</b><br>${esc(x.text)}</div>`)+block('관련구절',data.related,x=>`<div class="study-item"><b>${esc(x.reference)} · ${esc(x.translation)}</b>${x.semantic_score!==undefined?` · 유사도 ${Number(x.semantic_score).toFixed(3)}`:''}<br>${esc(x.text)}</div>`);$('studyMarkdown').textContent=data.note_markdown||''}
