function outlineProgressSet(percent,stage,summary,detail,title){const value=Math.max(0,Math.min(100,Math.round(percent)));$('outlineProgressPercent').textContent=value+'%';$('outlineProgressBar').style.width=value+'%';$('outlineProgressBar').parentElement.setAttribute('aria-valuenow',value);$('outlineProgressStage').textContent=stage;$('outlineProgressSummary').textContent=summary;$('outlineProgressDetail').textContent=detail;if(title)$('outlineProgressTitle').textContent=title}
function startOutlineProgress(model){const box=$('outlineProgress'),started=Date.now();box.hidden=false;$('cancelOutline').disabled=false;$('outlineProgressModel').textContent='모델 · '+model;outlineProgressSet(8,'1 · 준비','중심본문과 선택 시간을 읽고 있습니다.','요청을 준비 중입니다.');clearInterval(outlineProgressTimer);outlineProgressTimer=setInterval(()=>{$('outlineProgressElapsed').textContent=Math.floor((Date.now()-started)/1000)+'초'},1000);const steps=[[22,'2 · 본문 근거 확인','등록된 성경 근거와 생성 조건을 확인합니다.','본문 근거 판정 중입니다.'],[42,'3 · 구조 설계','핵심 메시지와 세 대지의 방향을 설계합니다.','LM Studio에 구조 생성을 요청했습니다.'],[72,'4 · LM Studio 생성','본문 근거 안에서 3대지 초안을 생성하고 있습니다.','모델 응답을 기다리는 중입니다.'],[92,'5 · 검증','시간 배분과 각 대지의 본문 연결을 검증합니다.','생성 결과를 검증할 준비 중입니다.']];let i=0;const timer=setInterval(()=>{if(i<steps.length){outlineProgressSet(...steps[i++])}else clearInterval(timer)},1800);return{finish(d){clearInterval(timer);clearInterval(outlineProgressTimer);$('outlineProgressElapsed').textContent=Math.floor((Date.now()-started)/1000)+'초';outlineProgressSet(100,'완료','3대지 구조가 생성되어 화면에 표시되었습니다.','성공적으로 완료했습니다.','3대지 구조 생성 완료');$('cancelOutline').disabled=true},fail(message){clearInterval(timer);clearInterval(outlineProgressTimer);outlineProgressSet(0,'중단','3대지 구조가 생성되지 않았습니다.',message,'3대지 구조 생성 중단');$('cancelOutline').disabled=true}}}
async function buildSermonOutline(){const topic=$('topic').value.trim(),reference=$('reference').value.trim(),model=$('model').value;if(!topic||!reference){alert('설교 주제와 중심본문을 먼저 입력하세요.');return}if(!model){alert('LM Studio 생성 모델을 먼저 로드하세요.');return}const body={topic,details:$('details').value,main_reference:reference,audience:$('audience').value,tradition:$('tradition').value,minutes:Number($('minutes').value),model,reading_cpm:Number($('readingCpm').value||330)};const btn=$('buildOutline');btn.disabled=true;const progress=startOutlineProgress(model);$('outlineStatus').textContent='Preflight와 같은 중심본문 근거 판정으로 확인한 뒤 8K 안전 예산에서 3대지 구조를 만들고 있습니다…';try{const r=await fetch('/api/outline',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await apiJson(r,'설교 구조 생성 실패');if(!r.ok)throw new Error(d.detail||'설교 구조 생성 실패');if(d.reference)$('reference').value=d.reference;currentOutline={...d.outline,time_plan:d.time_plan,reference:d.reference,model:d.model,prompt_budget:d.prompt_budget};renderOutline(currentOutline);$('lmRecoveryStatus').className='lm-recovery-status hidden';progress.finish(d)}catch(e){currentOutline=null;clearOutlineView();$('outlineStatus').textContent='오류: '+e.message;progress.fail(e.name==='AbortError'?'사용자가 현재 작업을 취소했습니다.':e.message);if(/LM Studio|chat\/completions|추론 연결/.test(e.message))renderLmRecovery({ready:false,message:'LM Studio 연결 상태를 단계별로 다시 확인하세요.',steps:[{ok:false,label:'3대지 추론',detail:e.message}]})}finally{btn.disabled=false}}
function renderOutline(outline){const plan=outline.time_plan||{},sections=plan.sections||[],sum=sections.reduce((n,x)=>n+Number(x.minutes||0),0),budget=outline.prompt_budget||{};$('timePlan').innerHTML=sections.map(x=>`<div class="time-slot"><small>${esc(x.label)}</small><b>${Number(x.minutes)}분</b><small>약 ${Number(x.target_chars).toLocaleString()}자</small></div>`).join('');$('outlineSummary').innerHTML=`<h3>${esc(outline.title||'설교 구조')}</h3><div><b>핵심 메시지</b> · ${esc(outline.core_message||'')}</div><small>선택 ${Number(plan.target_minutes||0)}분 · 배분 합계 ${sum}분 · ${Number(plan.reading_cpm||0)}자/분</small>`;$('outlinePoints').innerHTML=(outline.points||[]).map((p,i)=>`<article class="outline-point"><h4>${i+1}. ${esc(p.title)}</h4><small>${esc(p.reference)}</small><p>${esc(p.explanation)}</p><p><b>적용</b> ${esc(p.application)}</p><small>예화 방향: ${esc(p.illustration_direction)}</small></article>`).join('');const safe=budget.mode?` · 컨텍스트 안전화 ${Number(budget.input_chars||0).toLocaleString()}자 · 원어 ${Number(budget.original_used||0)}/${Number(budget.original_total||0)}건 사용`:'';$('outlineStatus').textContent=sum===Number(plan.target_minutes)?`시간 검증 정상 · ${sum}분 합계 · 등록 본문 근거로 3대지 구성 완료${safe}`:`시간 합계 확인 필요 · 선택 ${Number(plan.target_minutes)}분 / 배분 ${sum}분`}
function clearOutlineView(){currentOutline=null;$('timePlan').innerHTML='';$('outlineSummary').innerHTML='';$('outlinePoints').innerHTML='';$('outlineStatus').textContent='저장된 설교 구조가 없습니다. 필요하면 3대지 구조를 새로 만드세요.'}

function notebookReference(){return $('reference').value.trim()||$('studyReference').value.trim()}
async function loadNotebookStatus(){
  const reference=notebookReference(),q=reference?'?reference='+encodeURIComponent(reference):'';
  try{
    const r=await fetch('/api/notebooklm/status'+q,{cache:'no-store'}),d=await apiJson(r,'Notebook 연결 상태 조회 실패');
    if(!r.ok)throw new Error(d.detail||'Notebook 연결 상태 조회 실패');
    const drive=d.drive||{};$('notebookDriveFolder').value=drive.folder||'';
    $('notebookDriveStatus').className='import-status '+(drive.ready?'ok':drive.configured?'bad':'warn');
    $('notebookDriveStatus').textContent=drive.ready?'사용 가능 · '+drive.folder:drive.message;
    renderNotebookNotes(d.notes||[]);
  }catch(e){$('notebookDriveStatus').className='import-status bad';$('notebookDriveStatus').textContent=e.message}
}
async function saveNotebookDrive(clear=false){
  const folder=clear?'':$('notebookDriveFolder').value.trim(),btn=clear?$('clearNotebookDrive'):$('saveNotebookDrive');btn.disabled=true;
  $('notebookDriveStatus').className='import-status';$('notebookDriveStatus').textContent=clear?'설정을 해제하고 있습니다…':'폴더 존재 여부와 쓰기 권한을 시험하고 있습니다…';
  try{const r=await fetch('/api/notebooklm/drive',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({folder})}),d=await apiJson(r,'Drive 폴더 설정 실패');if(!r.ok)throw new Error(d.detail||'Drive 폴더 설정 실패');$('notebookDriveFolder').value=d.folder||'';$('notebookDriveStatus').className='import-status '+(d.ready?'ok':'warn');$('notebookDriveStatus').textContent=d.message+(d.folder?' · '+d.folder:'')}catch(e){$('notebookDriveStatus').className='import-status bad';$('notebookDriveStatus').textContent='설정 실패 · '+e.message}finally{btn.disabled=false}
}
async function createNotebookPack(){
  const reference=notebookReference();if(!reference){alert('설교 요청의 중심본문을 먼저 입력하세요.');return}
  if(!$('notebookCloudConfirm').checked){alert('저작권·개인정보·클라우드 전송 주의사항 확인란을 먼저 선택하세요.');return}
  const btn=$('createNotebookPack');btn.disabled=true;$('notebookPackDownload').classList.add('hidden');$('notebookPackStatus').className='import-status';$('notebookPackStatus').textContent='등록 근거를 검사하고 Notebook 자료팩을 만들고 있습니다…';
  const body={topic:$('topic').value.trim(),main_reference:reference,tradition:$('tradition').value,minutes:Number($('minutes').value),sync_to_drive:$('notebookSyncDrive').checked,confirmed_cloud_export:true};
  try{const r=await fetch('/api/notebooklm/pack',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}),d=await apiJson(r,'Notebook 자료팩 생성 실패');if(!r.ok)throw new Error(d.detail||'Notebook 자료팩 생성 실패');const drive=d.drive_path?` · Drive 복사 완료: ${d.drive_path}`:d.drive_warning?` · Drive 복사는 건너뜀: ${d.drive_warning}`:'';$('notebookPackStatus').className='import-status ok';$('notebookPackStatus').textContent=`자료팩 완성 · ${d.files.length}개 파일 · SHA-256 검증${drive}`;$('notebookPackDownload').href=d.url;$('notebookPackDownload').download=d.filename;$('notebookPackDownload').classList.remove('hidden')}catch(e){$('notebookPackStatus').className='import-status bad';$('notebookPackStatus').textContent='생성 실패 · '+e.message}finally{btn.disabled=false}
}
function renderNotebookNotes(items){$('notebookNoteList').innerHTML=items.length?items.map(x=>`<div class="notebook-note-item"><b>${esc(x.title)}</b><small>${esc(x.created_at)} · 인용 표시 ${Number(x.citation_count||0)}개 · ${x.verification_status==='unverified'?'미검증':'목회자 검토 필요'}</small></div>`).join(''):'<div class="notebook-note-item">이 중심본문에 가져온 외부 연구노트가 없습니다.</div>'}
async function refreshNotebookNotes(){const reference=notebookReference();if(!reference){$('notebookNoteStatus').className='import-status warn';$('notebookNoteStatus').textContent='중심본문을 먼저 입력하세요.';return}try{const r=await fetch('/api/notebooklm/notes?reference='+encodeURIComponent(reference),{cache:'no-store'}),d=await apiJson(r,'연구노트 조회 실패');if(!r.ok)throw new Error(d.detail||'연구노트 조회 실패');renderNotebookNotes(d.items||[]);$('notebookNoteStatus').className='import-status '+((d.items||[]).length?'ok':'warn');$('notebookNoteStatus').textContent=(d.items||[]).length?`외부 연구노트 ${(d.items||[]).length}개 · 성경·원어 DB와 분리 보관`:'아직 가져온 연구 결과가 없습니다.'}catch(e){$('notebookNoteStatus').className='import-status bad';$('notebookNoteStatus').textContent=e.message}}
async function importNotebookNote(){const reference=notebookReference(),content=$('notebookNoteContent').value.trim();if(!reference){alert('중심본문을 먼저 입력하세요.');return}if(!content){alert('Notebook 연구 결과와 인용을 붙여넣으세요.');return}const btn=$('importNotebookNote');btn.disabled=true;$('notebookNoteStatus').className='import-status';$('notebookNoteStatus').textContent='인용 표시를 검사하고 외부 연구노트로 분리 저장하고 있습니다…';try{const r=await fetch('/api/notebooklm/notes',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reference,title:$('notebookNoteTitle').value.trim(),content,sermon_id:currentSermonId})}),d=await apiJson(r,'연구 결과 가져오기 실패');if(!r.ok)throw new Error(d.detail||'연구 결과 가져오기 실패');$('notebookNoteStatus').className='import-status '+(d.citation_count?'ok':'warn');$('notebookNoteStatus').textContent=`가져오기 완료 · 인용 표시 ${Number(d.citation_count)}개 · ${d.message}`;$('notebookNoteContent').value='';await refreshNotebookNotes()}catch(e){$('notebookNoteStatus').className='import-status bad';$('notebookNoteStatus').textContent='가져오기 실패 · '+e.message}finally{btn.disabled=false}}
$('saveNotebookDrive').onclick=()=>saveNotebookDrive(false);$('clearNotebookDrive').onclick=()=>saveNotebookDrive(true);$('createNotebookPack').onclick=createNotebookPack;$('importNotebookNote').onclick=importNotebookNote;$('refreshNotebookNotes').onclick=refreshNotebookNotes;
$('minutes').addEventListener('change',()=>{invalidatePreflight();if(currentOutline&&Number(currentOutline.time_plan?.target_minutes)!==Number($('minutes').value))$('outlineStatus').textContent='설교 시간이 바뀌었습니다. 새 시간에 맞게 3대지 구조를 다시 만드세요.'});
$('reference').addEventListener('input',()=>{invalidatePreflight();if(currentOutline&&currentOutline.reference!==$('reference').value.trim())$('outlineStatus').textContent='중심본문이 바뀌었습니다. 본문 연구와 설교 구조를 다시 확인하세요.'});
['topic','details'].forEach(id=>$(id).addEventListener('input',()=>invalidatePreflight()));
['tradition','audience','useRag'].forEach(id=>$(id).addEventListener('change',()=>invalidatePreflight()));
$('readingCpm').addEventListener('change',()=>invalidatePreflight());
function paintWizard(steps,label){const states=steps.map(x=>x?.status||'pending');const buttons=[...document.querySelectorAll('#wizardSteps button')];buttons.forEach((button,i)=>{const state=states[i]||'pending';button.classList.remove('completed','attention','pending');button.classList.add(state);button.title=steps[i]?.detail||''});document.querySelectorAll('#workflowRailSteps button').forEach((button,i)=>{const state=states[i]||'pending';button.classList.remove('completed','attention','pending');button.classList.add(state);button.title=steps[i]?.detail||''});$('wizardCount').textContent=label;const next=steps.find(x=>x.status!=='completed');$('wizardMessage').textContent=next?`다음 확인: ${next.title} · ${next.detail}`:'7단계가 모두 완료되었습니다. 최종 잠금본을 출력할 수 있습니다.'}
function renderLocalWorkflow(data){renderMediaPrompts(data.media_prompts);const translations=new Set((data.sources||[]).map(x=>x.translation).filter(Boolean));const languageReady=translations.size>=2||(data.original_notes||[]).length>0;const auditReady=data.audit?.status==='ready_for_review';paintWizard([
  {status:'completed',title:'1. 주제·본문 설정',detail:$('reference').value||'설교 요청 입력 완료'},
  {status:data.source_count?'completed':'attention',title:'2. 성경 본문 연구',detail:`등록 근거 ${Number(data.source_count||0)}건`},
  {status:languageReady?'completed':'attention',title:'3. 번역·원어 비교',detail:`번역/자료 ${translations.size}종 · 원어 노트 ${(data.original_notes||[]).length}건`},
  {status:'completed',title:'4. 설교 초안',detail:'LM Studio 초안 생성 완료'},
  {status:auditReady?'completed':'attention',title:'5. 근거 검증',detail:`Audit: ${data.audit?.status||'없음'}`},
  {status:'pending',title:'6. 목회자 검토·승인',detail:'버전 저장 후 검토하세요.'},
  {status:'pending',title:'7. 최종 잠금·출력',detail:'승인 및 잠금이 필요합니다.'}
],'초안 생성 · 저장 전');loadPreviewOptions()}
let latestProjectSummary=null;
function renderProjectSummary(d){latestProjectSummary=d;const latest=d.latest,files=latest?.files||[];$('workSummaryVersion').textContent=`V${d.app_version||'?'}`;$('workSummaryCommitCount').textContent=String((d.commits||[]).length);$('workSummaryChangedState').textContent=d.working_tree==='clean'?'정상':'변경 있음';$('workSummaryChangedFiles').textContent=String(files.length);$('workSummarySummary').textContent=latest?`${latest.subject} · ${latest.hash} · ${latest.date} · ${latest.areas?.join(' · ')||'프로젝트 변경'}`:'Git 이력을 사용할 수 없어 기본 요약을 표시합니다.';if($('changesGrid'))$('changesGrid').innerHTML=(d.commits||[]).map((c,i)=>`<article class="change-card ${i===0?'current':''}"><div class="change-card-head"><span>${esc(c.date)} · ${esc(c.hash)}</span><b>${i===0?'최신':'기록'}</b></div><h3>${esc(c.subject)}</h3><ul><li>영역: ${esc(c.areas?.join(' · ')||'프로젝트')}</li><li>변경 파일 ${Number(c.files?.length||0)}개 · Git 기록에서 자동 수집</li><li>${esc((c.files||[]).slice(0,4).join(', ')||'파일 정보 없음')}</li></ul></article>`).join('');if($('workSummaryRecent'))$('workSummaryRecent').innerHTML=latest?`<div class="work-summary-row head"><b>커밋</b><b>날짜</b><b>영역</b><b>자동 요약</b></div>${(d.commits||[]).slice(0,8).map(c=>`<div class="work-summary-row"><span>${esc(c.hash)}</span><span>${esc(c.date)}</span><em>${esc(c.areas?.join(' · ')||'프로젝트')}</em><span>${esc(c.subject)} · ${Number(c.files?.length||0)}개 파일</span></div>`).join('')}`:'<div class="work-summary-row"><span>Git</span><span>사용 불가</span><em>fallback</em><span>기본 화면 내용을 유지합니다.</span></div>'}
async function loadProjectSummary(){try{const r=await fetch('/api/project-summary',{cache:'no-store'}),d=await r.json();if(!r.ok)throw new Error(d.detail||'프로젝트 요약 조회 실패');renderProjectSummary(d)}catch(e){if($('workSummarySummary'))$('workSummarySummary').textContent='자동 변경사항을 불러오지 못했습니다. 기본 요약을 표시합니다.'}}
const workSummaryMarkdown=()=>`# Sermon LM Studio 작업 종합 대시보드\n\n- 제품 버전: V40.9.10\n- 현재 판정: PASS WITH WARNINGS\n- 전체 pytest: 220 passed\n- failed / error: 0\n- 완료 단계: 17\n- Web Grounding 기본값: OFF\n\n## 단계별 진행 현황\n\n| 영역 | 단계 | 상태 | 핵심 결과 |\n|---|---|---|---|\n| 구조 분리 | Phase 1C-1~1C-5 | 완료 | Settings / Project / Doctrine / Bible / Sermon Repository |\n| 서비스·RAG | Phase 1D~2B | 완료 | Sermon Service, FTS5 선택, RRF 선택 |\n| 근거·검증 | Phase 2C~2F | 완료 | Evidence, Validator, Audit, Dashboard, Report Export |\n| Router | Phase 3A | 완료 | health / settings / projects / doctrine / bible / exports |\n| Web Grounding | Phase 3B | 완료 | 선택형 generic HTTP adapter, runtime Tier D |\n| Provider 평가 | Phase 3C | 경고 포함 | 30 query mock 평가 완료, live 평가 대기 |\n\n## 안전·호환성\n\n- 기존 API URL·응답 형식 유지\n- SQLite schema·데이터 변경 없음\n- Script 중심본문 검증 유지\n- Tier A/B/C 정책 변경 없음`;
function downloadWorkSummary(name,content,type){const version=($('runtimeVersion')?.textContent||'V40.9.10').replace(/^V/,'');name=name.replace(/40\.9\.[0-9]+/,version);content=content.replace(/V40\.9\.[0-9]+/g,`V${version}`).replace(/40\.9\.[0-9]+/g,version);const blob=new Blob([content],{type:`${type};charset=utf-8`}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),500)}
