async function installOfficialOriginal(){const btn=$('installOfficialOriginal'),box=$('officialInstallProgress');if(!btn||!box)return;btn.disabled=true;box.hidden=false;let timer;const paint=d=>{const value=Math.max(0,Math.min(100,Number(d.percent||0)));$('officialInstallStage').textContent=d.stage||'설치 중';$('officialInstallPercent').textContent=`${value}%`;$('officialInstallBar').style.width=`${value}%`;$('officialInstallBar').parentElement.setAttribute('aria-valuenow',String(value));$('officialInstallCurrent').textContent=d.current?`현재 파일 · ${d.current}`:'현재 파일 · 준비 중';$('officialInstallMessage').textContent=d.message||'';if(d.results?.length)$('officialInstallResults').innerHTML=d.results.map(x=>`<div><b>${esc(x.label)}</b><span>${esc(x.detail)}</span></div>`).join('')};try{let r=await fetch('/api/import/original-language/install-official',{method:'POST'}),d=await r.json();if(!r.ok)throw new Error(d.detail||'공식 원어 자료 설치를 시작하지 못했습니다.');paint(d);timer=setInterval(async()=>{try{const q=await fetch('/api/import/original-language/install-official/status',{cache:'no-store'}),s=await q.json();paint(s);if(s.state==='completed'||s.state==='failed'){clearInterval(timer);btn.disabled=false;if(s.state==='completed'){await loadDatabaseDashboard();await checkHealth();$('smartOriginalStatus').className='import-status ok';$('smartOriginalStatus').textContent='공식 SBLGNT·MorphGNT 자료 설치와 원어 DB 등록이 완료되었습니다.'}else{$('smartOriginalStatus').className='import-status bad';$('smartOriginalStatus').textContent=`공식 자료 설치 중단 · ${s.message||'서버 로그를 확인하세요.'}`}}}catch(e){clearInterval(timer);btn.disabled=false;$('smartOriginalStatus').className='import-status bad';$('smartOriginalStatus').textContent='설치 상태 확인 실패 · '+e.message}},700)}catch(e){btn.disabled=false;box.hidden=false;$('officialInstallStage').textContent='설치 시작 실패';$('officialInstallMessage').textContent=e.message}}
