async function lookupGreekMorphology(){const input=$('greekLookupReference'),status=$('greekLookupStatus'),result=$('greekLookupResult'),button=$('lookupGreekMorphology');if(!input||!status||!result)return;const reference=input.value.trim();if(!reference){status.className='import-status warn';status.textContent='조회할 성경 참조를 입력하세요.';return}button.disabled=true;status.className='import-status';status.textContent='성경 참조를 정규화하고 MorphGNT token을 조회하고 있습니다…';result.innerHTML='';try{const infoResponse=await fetch(`/api/reference-info?reference=${encodeURIComponent(reference)}`),info=await apiJson(infoResponse,'성경 참조 확인 실패');if(!infoResponse.ok)throw new Error(info.detail||'성경 참조 확인 실패');const parts=info.first_reference.split(/\s+|:/),r=await fetch(`/api/bible/greek/${encodeURIComponent(info.book)}/${parts[1]}/${parts[2]}/morphology`),d=await apiJson(r,'헬라어 형태론 조회 실패');if(!r.ok)throw new Error(d.detail||'헬라어 형태론 조회 실패');if(d.source_status!=='available'){status.className='import-status warn';status.textContent=d.source_status==='unavailable_in_source'?'이 구간은 MorphGNT 원본에 형태론 자료가 없습니다. 자동 보완하지 않습니다.':'해당 본문의 MorphGNT 자료가 아직 등록되지 않았습니다.';return}status.className='import-status ok';status.textContent=`조회 완료 · ${d.display_reference} · ${d.tokens.length}개 token · 출처 ${d.tokens[0]?.source?.version||'-'}`;result.innerHTML=`<div class="greek-lookup-source"><b>${esc(d.display_reference)}</b><span>${esc(d.tokens[0]?.source?.file||'')} · checksum ${esc((d.tokens[0]?.source?.sha256||'').slice(0,12))}…</span></div><div class="greek-token-grid">${d.tokens.map(t=>`<article><b>${esc(t.text)}</b><span>${esc(t.lemma)}</span><small>${esc(t.pos)} · ${esc(t.parsing_raw)}</small><em>${esc(Object.values(t.morphology).filter(Boolean).join(' · ')||'형태 정보 없음')}</em></article>`).join('')}</div>`}catch(e){status.className='import-status bad';status.textContent=e.message}finally{button.disabled=false}}
