async function loadGreekAlignment(){const input=$('greekLookupReference'),result=$('greekAlignmentResult');if(!input||!result)return;const reference=input.value.trim();if(!reference)return;try{const infoResponse=await fetch(`/api/reference-info?reference=${encodeURIComponent(reference)}`),info=await apiJson(infoResponse,'성경 참조 확인 실패');if(!infoResponse.ok)throw new Error(info.detail||'성경 참조 확인 실패');const parts=info.first_reference.split(/\s+|:/),r=await fetch(`/api/bible/greek/${encodeURIComponent(info.book)}/${parts[1]}/${parts[2]}/alignment`),d=await apiJson(r,'Alignment 조회 실패');if(!r.ok)throw new Error(d.detail||'Alignment 조회 실패');const labels={MATCHED:['일치','SBLGNT와 MorphGNT token이 일치합니다.','ok'],NORMALIZATION_ONLY:['정규화 차이','Unicode 또는 문장부호 차이만 있습니다.','ok'],TOKENIZATION_DIFFERENCE:['tokenization 차이',`token 수가 다릅니다 · SBLGNT ${d.sblgnt_token_count}개 / MorphGNT ${d.morphgnt_token_count}개`,'warn'],TEXT_DIFFERENCE:['표면형 차이','token 수는 같지만 표면형이 다릅니다. 원문은 자동 수정하지 않습니다.','warn'],UNRESOLVED:['연결 미확정',d.reason==='sblgnt_source_missing'?'SBLGNT 원문 파일이 없습니다.':'MorphGNT 또는 SBLGNT 연결 자료가 없습니다.','bad']};const label=labels[d.status]||['확인 필요','Alignment 상태를 확인하세요.','bad'];result.innerHTML=`<div class="greek-alignment-strip ${label[2]}"><b>Alignment · ${esc(label[0])}</b><span>${esc(label[1])}</span><small>진단용 결과 · 원문/형태론 자동 변경 없음</small></div>`}catch(e){result.innerHTML=`<div class="greek-alignment-strip bad"><b>Alignment 조회 실패</b><span>${esc(e.message)}</span></div>`}}
