function renderMediaPrompts(packet){const box=$('mediaPromptsResults'),notice=$('mediaPromptsNotice');if(!box||!notice)return;if(!packet||!Array.isArray(packet.sections)){box.innerHTML='';notice.textContent='설교 생성 후 근거 기반 예화·이미지·영상 프롬프트가 표시됩니다.';return}notice.textContent=packet.notice||'';box.innerHTML=packet.sections.map(s=>`<article class="media-prompt-section"><h3>${esc(s.title)} / ${esc(s.english_title)}</h3><small>근거: ${esc(s.biblical_references)}</small>${['anecdote','image','video'].map(k=>{const p=s.prompts?.[k]||{};return `<details open><summary>[${esc(p.label||k)}] 한국어 · English</summary><p><b>한국어</b><br>${esc(p.ko||'')}</p><p><b>English</b><br>${esc(p.en||'')}</p></details>`}).join('')}</article>`).join('')}
async function loadGithubSettings(){try{const r=await fetch('/api/settings/github',{cache:'no-store'}),d=await r.json();if(r.ok)$('githubRepositoryUrl').value=d.repository_url||''}catch(e){$('githubSettingsStatus').textContent='GitHub 설정 조회 실패: '+e.message}}
async function saveGithubSettings(){const btn=$('saveGithubSettings');btn.disabled=true;try{const r=await fetch('/api/settings/github',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({repository_url:$('githubRepositoryUrl').value.trim()})}),d=await r.json();if(!r.ok)throw new Error(d.detail||'GitHub 설정 저장 실패');$('githubRepositoryUrl').value=d.repository_url||'';$('githubSettingsStatus').className='field-hint ok';$('githubSettingsStatus').textContent=d.repository_url?'GitHub 저장소 주소를 로컬 설정에 저장했습니다. 자동 push는 실행하지 않습니다.':'GitHub 저장소 설정을 해제했습니다.';await runReadiness()}catch(e){$('githubSettingsStatus').className='field-hint bad';$('githubSettingsStatus').textContent='저장 실패 · '+e.message}finally{btn.disabled=false}}
if($('saveGithubSettings')){$('saveGithubSettings').onclick=saveGithubSettings;loadGithubSettings()}

