if($('workSummaryMarkdown'))$('workSummaryMarkdown').onclick=()=>downloadWorkSummary('sermon-lmstudio-work-summary-v40.9.10.md',`# Sermon LM Studio 작업 종합 대시보드\n\n- 제품 버전: V40.9.10\n- 기준일: 2026-09-04\n- 판정: 최적화 완료 · 검증 통과\n- 전체 pytest: 361 passed, 11 skipped\n\n## 완료 작업\n\n- 설교 15·20·25·30분 시간별 모델 자동선택 및 수동 선택 고정\n- Qwen 추론 출력 제외, 장문 생성 예산 및 후속 생성 보강\n- SBLGNT·MorphGNT·Apparatus·OSHB 원어 자료와 발음기호 표시 흐름\n- 원어·성경 근거·승인·출력 안전성 유지\n- 설치및 사용 안내서와 폴더 구조·장애 대응·정상상태 복구 도구 추가\n\n## 복구\n\n\`.\\scripts\\restore_known_good.ps1\`는 미리보기, \`-Apply\`는 변경사항 패치 보관 후 추적 파일을 현재 기준 커밋으로 복구합니다. 사용자 DB·백업·출력물은 삭제하지 않습니다.\n\n## 호환성\n\n- 기존 API·SQLite·일반 RAG·LM Studio localhost 주소 유지\n- Web Grounding 기본값 OFF\n- 원어 자료는 출처·checksum·사용조건을 보존`,'text/markdown');
const nativeFetch=window.fetch.bind(window);
function cancelGeneration(){if(!generationId)return;const id=generationId;$('cancelGeneration').disabled=true;nativeFetch('/api/sermons/cancel',{method:'POST',headers:{'X-Generation-Id':id}}).catch(()=>{});generationController?.abort();$('generationProgressTitle').textContent='설교 생성 취소를 요청했습니다';$('generationProgressDetail').textContent='LM Studio의 현재 요청을 중지하고 있습니다.'}
function cancelOutlineGeneration(){if(!outlineGenerationId)return;const id=outlineGenerationId;$('cancelOutline').disabled=true;nativeFetch('/api/sermons/cancel',{method:'POST',headers:{'X-Generation-Id':id}}).catch(()=>{});outlineController?.abort();$('outlineProgressTitle').textContent='3대지 생성 취소를 요청했습니다';$('outlineProgressDetail').textContent='LM Studio의 현재 요청을 중지하고 있습니다.'}
window.fetch=(input,init={})=>{const url=typeof input==='string'?input:input?.url||'';if(url.endsWith('/api/sermons')&&init.method==='POST'){generationController=new AbortController;generationId=`${Date.now()}-${Math.random()}`;return nativeFetch(input,{...init,signal:generationController.signal,headers:{...(init.headers||{}),'X-Generation-Id':generationId}})}if(url.endsWith('/api/outline')&&init.method==='POST'){outlineController=new AbortController;outlineGenerationId=`${Date.now()}-${Math.random()}`;return nativeFetch(input,{...init,signal:outlineController.signal,headers:{...(init.headers||{}),'X-Generation-Id':outlineGenerationId}})}return nativeFetch(input,init)};
if($('cancelGeneration'))$('cancelGeneration').onclick=cancelGeneration;
if($('cancelOutline'))$('cancelOutline').onclick=cancelOutlineGeneration;
function syncWorkflowRailCurrent(){const buttons=[...document.querySelectorAll('#workflowRailSteps button')];if(!buttons.length)return;const current=buttons.findIndex(button=>!button.classList.contains('completed'));buttons.forEach((button,index)=>{const active=index===current;button.classList.toggle('current',active);if(active)button.setAttribute('aria-current','step');else button.removeAttribute('aria-current')})}
if($('workflowRailSteps')){document.querySelectorAll('#workflowRailSteps button[data-target]').forEach(button=>{button.addEventListener('click',()=>revealAndScroll(button.dataset.target))});const workflowObserver=new MutationObserver(syncWorkflowRailCurrent);workflowObserver.observe($('workflowRailSteps'),{subtree:true,attributes:true,attributeFilter:['class']});syncWorkflowRailCurrent()}

window.runtimeModelPolicy=window.runtimeModelPolicy||{};window.modelManualSelection=window.modelManualSelection||false;window.modelAutoApplying=false;
function applyAutomaticGenerationModel(){if(window.modelManualSelection)return;const fallbackPolicy={'15':['qwen/qwen3.5-9b','qwen/qwen3-8b'],'20':['qwen/qwen3.5-9b','qwen/qwen3-8b'],'25':['qwen/qwen3.5-27b','qwen/qwen3.5-9b','qwen/qwen3-8b'],'30':['qwen/qwen3.5-27b','qwen/qwen3.5-9b','qwen/qwen3-8b']},policy=Object.keys(window.runtimeModelPolicy||{}).length?window.runtimeModelPolicy:fallbackPolicy,ready=lastHealth?.generation_models||[],minutes=String(Number($('minutes')?.value||15)),candidates=policy[minutes]||[],chosen=candidates.map(candidate=>ready.find(model=>model===candidate||model.startsWith(candidate+':'))).find(Boolean)||ready[0]||'';window.modelAutoApplying=true;if($('model'))$('model').value=chosen;window.modelAutoApplying=false;if($('modelHint'))$('modelHint').textContent=chosen?`자동 추천 · ${chosen} · 필요 시 목록에서 수동 선택 가능`:'LM Studio READY 생성 모델 연결 후 자동 선택';}
function generationModelForRequest(){return window.modelManualSelection?$('model').value:''}
if($('model'))$('model').addEventListener('change',()=>{if(!window.modelAutoApplying)window.modelManualSelection=!!$('model').value;invalidatePreflight()});
if($('model'))$('model').addEventListener('change',()=>{if(!window.modelAutoApplying&&$('model').value&&$('modelHint')){$('modelHint').textContent=`수동 선택 · ${$('model').value} · 설교시간 변경 시에도 유지`;$('model').setAttribute('aria-label',`LM Studio 생성 모델 수동 선택 · ${$('model').value}`)}});
if($('minutes'))$('minutes').addEventListener('change',()=>{if(!window.modelManualSelection)applyAutomaticGenerationModel()});
if($('model'))new MutationObserver(()=>setTimeout(applyAutomaticGenerationModel,0)).observe($('model'),{childList:true});
fetch('/api/workflow/config',{cache:'no-store'}).then(r=>r.json()).then(d=>{window.runtimeModelPolicy=d.recommended_generation_models||{};applyAutomaticGenerationModel()}).catch(()=>{});

/* 모든 진행 패널이 같은 범위·progressbar·ETA 규칙을 사용한다. */
function normalizeProgress(value){return Math.max(0,Math.min(100,Math.round(Number(value)||0)))}
const progressClocks={generation:0,outline:0,rag:0};
function formatProgressEta(kind,percent){const id={generation:'generationProgressEta',outline:'outlineProgressEta',rag:'ragProgressEta'}[kind],node=$(id);if(!node)return;if(percent>=100){node.textContent='완료';return}if(percent<=0||!progressClocks[kind]){node.textContent='계산 중';return}const elapsed=Date.now()-progressClocks[kind],remaining=Math.min(24*60*60*1000,Math.max(0,elapsed*(100-percent)/percent)),eta=new Date(Date.now()+remaining);node.textContent=`약 ${Math.max(1,Math.ceil(remaining/1000))}초 후 · ${eta.toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit',second:'2-digit'})}`}
const baseGenerationProgress=startGenerationProgress,baseRagProgress=startRagProgress,baseOutlineProgress=startOutlineProgress;
startGenerationProgress=function(model){progressClocks.generation=Date.now();return baseGenerationProgress(model)};
startRagProgress=function(model){progressClocks.rag=Date.now();return baseRagProgress(model)};
startOutlineProgress=function(model){progressClocks.outline=Date.now();return baseOutlineProgress(model)};
const baseSetGenerationProgress=setGenerationProgress,baseSetRagProgress=setRagProgress,baseOutlineProgressSet=outlineProgressSet;
setGenerationProgress=function(percent,...args){const value=normalizeProgress(percent);formatProgressEta('generation',value);return baseSetGenerationProgress(value,...args)};
setRagProgress=function(percent,...args){const value=normalizeProgress(percent);formatProgressEta('rag',value);return baseSetRagProgress(value,...args)};
outlineProgressSet=function(percent,...args){const value=normalizeProgress(percent);formatProgressEta('outline',value);return baseOutlineProgressSet(value,...args)};

